{"command": "cat > /tmp/fdec.py <<'EOF'
import sys,hashlib,struct

class BR:
    __slots__=('d','pos','bp')
    def __init__(self,d,pos=0):
        self.d=d; self.pos=pos; self.bp=0
    def read(self,n):
        v=0
        for _ in range(n):
            v=(v<<1)|((self.d[self.pos]>>(7-self.bp))&1)
            self.bp+=1
            if self.bp==8: self.bp=0; self.pos+=1
        return v
    def readutf(self):
        v=self.read(8)
        if v<0x80: return v
        if v<0xC0: raise ValueError('bad utf8')
        if v<0xE0: return ((v&31)<<6)|self.read(6)
        if v<0xF0: return ((v&15)<<12)|(self.read(6)<<6)|self.read(6)
        return ((v&7)<<18)|(self.read(6)<<12)|(self.read(6)<<6)|self.read(6)
    def sread(self,n):
        v=self.read(n)
        return v-(1<<n) if v>=(1<<(n-1)) else v
    def align(self):
        if self.bp: self.bp=0; self.pos+=1

def rice(g,n):
    q=0
    while g.read(1)==0:
        q+=1
        if q>1<<24: raise ValueError('bad rice')
    r=g.read(n)
    v=(q<<n)|r
    return (v>>1)+1 if v&1 else -(v>>1)

def crc8(data):
    crc=0
    for c in data:
        crc^=c
        for _ in range(8):
            crc=((crc<<1)^7)&255 if crc&128 else (crc<<1)&255
    return crc
def crc16(data):
    crc=0
    for c in data:
        crc^=c<<8
        for _ in range(8):
            crc=((crc<<1)^0x8005)&0xffff if crc&0x8000 else (crc<<1)&0xffff
    return crc

def read_residuals(g,bs,order,dbg=False):
    po=g.read(4)
    np_=1<<po
    nv=bs>>po
    parts=[]
    for i in range(np_):
        rp=g.read(4)
        cnt=nv-order if i==0 else nv
        parts.append((rp,[rice(g,rp) for _ in range(cnt)]))
    return po,parts

def decode(path, dbg=False):
    d=open(path,'rb').read()
    i=4; si=None
    while True:
        t=d[i]; typ=t&0x7f; last=t>>7
        ln=int.from_bytes(d[i+1:i+4],'big')
        if typ==0: si=d[i+4:i+4+ln]
        i+=4+ln
        if last: break
    v=int.from_bytes(si[10:18],'big')
    sr=v>>44; ch=((v>>41)&7)+1; bps=((v>>36)&31)+1; tot=v&((1<<36)-1)
    md5=si[18:].hex()
    SZ={0:bps,1:8,2:12,3:bps,4:16,5:20,6:24,7:32}
    allsamp=[]; p=i; nf=0; info=[]
    while p<len(d):
        g=BR(d,p)
        sync=g.read(14); g.read(1); strat=g.read(1)
        bsc=g.read(4); src=g.read(4); chc=g.read(4); szc=g.read(3); g.read(1)
        num=g.readutf()
        bs=None
        if bsc==6: bs=g.read(8)+1
        elif bsc==7: bs=g.read(16)+1
        if src==12: g.read(8)
        elif src in (13,14): g.read(16)
        fcrc=g.read(8)
        assert crc8(d[p:g.pos-1])==fcrc, 'frame crc'
        sz=SZ[szc]
        nsub = chc+1 if chc<8 else (2 if chc in (8,9,10,12,13,14) else 4)
        subs=[]; modes=[]
        for c in range(nsub):
            g.read(1); t6=g.read(6); wb=g.read(1)
            wasted=0
            if wb:
                k=0
                while g.read(1)==0: k+=1
                wasted=k+1
            eff=sz-wasted
            if t6==0:
                val=g.sread(eff)
                s=[val]*bs
                modes.append('const(w=%d,val=%d)'%(wasted,val))
            elif t6==1:
                s=[g.sread(eff) for _ in range(bs)]
                modes.append('verb(w=%d)'%wasted)
            elif (t6>>3)==1:
                order=t6&7
                warm=[g.sread(eff) for _ in range(order)]
                po,parts=read_residuals(g,bs,order)
                res=[x for _,pv in parts for x in pv]
                out=list(warm)
                for k in range(len(res)):
                    acc=0
                    if order>=1: acc+=out[-1]
                    if order>=2: acc+=2*out[-2]-out[-3]
                    if order>=3: acc+=3*out[-3]-3*out[-4]+out[-5]
                    if order>=4: acc+=4*out[-4]-6*out[-5]+4*out[-6]-out[-7]
                    out.append(res[k]+acc)
                s=out
                modes.append('fixed%d(w=%d,po=%d,rp=%s)'%(order,wasted,po,[a for a,_ in parts]))
            elif (t6>>5)==1:
                order=(t6&31)+1
                warm=[g.sread(eff) for _ in range(order)]
                prec=g.read(4)+1
                shift=g.read(5)
                coef=[g.sread(prec) for _ in range(order)]
                po,parts=read_residuals(g,bs,order)
                res=[x for _,pv in parts for x in pv]
                out=list(warm)
                for k in range(len(res)):
                    acc=sum(coef[j]*out[-1-j] for j in range(order))
                    out.append(res[k]+(acc>>shift))
                s=out
                modes.append('lpc%d(w=%d,prec=%d,shift=%d,po=%d,rp=%s,coef=%s)'%(order,wasted,prec,shift,po,[a for a,_ in parts],coef))
            else:
                raise ValueError('unknown t6=%d'%t6)
            subs.append(s)
        if dbg: print('  frame%d bs=%d num=%d strat=%d bsc=%d chc=%d szc=%d %s'%(nf,bs,num,strat,bsc,chc,szc,' | '.join(modes)))
        if chc==8:
            for k in range(bs): subs[1][k]=subs[0][k]+subs[1][k]
        elif chc==9:
            for k in range(bs): subs[0][k]=subs[0][k]+subs[1][k]
        elif chc==10:
            m=subs[0]; r=subs[1]
            for k in range(bs):
                l=m[k]+(r[k]>>1)
                subs[0][k]=l; subs[1][k]=l-r[k]
        allsamp.append((subs,bs))
        ecrc=g.read(16)
        g.align()
        p=g.pos
        nf+=1
    data=bytearray()
    for chans,bs2 in allsamp:
        for k in range(bs2):
            for cc in range(ch):
                data+=((chans[cc][k])&0xffff).to_bytes(2,'little')
    h=hashlib.md5(bytes(data)).hexdigest()
    if dbg or h!=md5:
        print(path,'frames=%d md5=%s expect=%s %s'%(nf,h,md5,'OK' if h==md5 else 'FAIL'))
    return bytes(data),(ch,bps,sr,tot),nf

if __name__=='__main__':
    dbg=len(sys.argv)>2 and sys.argv[2]=='dbg'
    for f in sys.argv[1:]:
        try:
            decode(f,dbg)
        except Exception as e:
            print(f,'ERR',repr(e))
