    return crc
def utf8(n):
    if n<0x80: return bytes([n])
    if n<0x800: return bytes([0xC0|(n>>6), 0x80|(n&63)])
    if n<0x10000: return bytes([0xE0|(n>>12), 0x80|((n>>6)&63), 0x80|(n&63)])
    return bytes([0xF0|(n>>18), 0x80|((n>>12)&63), 0x80|((n>>6)&63), 0x80|(n&63)])

def rice_encode(vals, k):
    w=BW()
    for x in vals:
        u = (x<<1) if x>=0 else (-x<<1)-1
        q = u>>k; r = u&((1<<k)-1)
        for _ in range(q): w.put(0,1)
        w.put(1,1)
        if k: w.put(r,k)
    return w

def make_flac(path, samples, sr=44100, ch=1, bps=16, layout='A', order=8, prec=15, shift=0, coefs=None):
    pcm=bytearray()
