    md5=hashlib.md5(bytes(pcm)).hexdigest()
    bs=len(samples)
    si=bytearray()
    si+=struct.pack('>HH',bs,bs)
    si+=struct.pack('>I',0)[1:]+struct.pack('>I',0)[1:]  # min/max framesize (3 bytes each)
    v=(sr<<44)|((ch-1)<<41)|((bps-1)<<36)|len(samples)
