    subprocess.run(['/workspace/executable','-v','error','-y']+extra+['-i',wav,out],stdin=subprocess.DEVNULL,capture_output=True)
    return out

def params(flac):
    d=open(flac,'rb').read()
    i=4; si=None
    while True:
        t=d[i]; typ=t&0x7f; last=t>>7
        ln=int.from_bytes(d[i+1:i+4],'big')
        if typ==0: si=d[i+4:i+4+ln]
        i+=4+ln
        if last: break
    v=int.from_bytes(si[10:18],'big')
    sr=v>>44; ch=((v>>41)&7)+1; bps=((v>>36)&31)+1; tot=v&((1<<36)-1)
    res=[]
    p=i
    while p<len(d):
        g=BR(d,p)
        g.read(14); g.read(1); strat=g.read(1)
        bsc=g.read(4); src=g.read(4); chc=g.read(4); szc=g.read(3); g.read(1)
        g.readutf()
        bs=None
        if bsc==6: bs=g.read(8)+1
        elif bsc==7: bs=g.read(16)+1
        if src==12: g.read(8)
        elif src in (13,14): g.read(16)
        g.read(8)
        SZ={0:bps,1:8,2:12,3:bps,4:16,5:20,6:24,7:32}
        sz=SZ[szc]
        nsub=chc+1 if chc<8 else (2 if chc in (8,9,10,12,13,14) else 4)
        subs=[]
        for c in range(nsub):
            g.read(1); t6=g.read(6); wb=g.read(1)
            wasted=0
            if wb:
                k=0
                while g.read(1)==0: k+=1
                wasted=k+1
            eff=sz-wasted
            if t6==0:
                subs.append(('const',g.sread(eff),wasted))
            elif t6==1:
                subs.append(('verb',wasted))
                for _ in range(bs): g.sread(eff)
            elif (t6>>3)==1:
                order=t6&7
                for _ in range(order): g.sread(eff)
                mt=g.read(2); po=g.read(4)
                np_=1<<po; nv=bs>>po
                rps=[]
                for k in range(np_):
                    rp=g.read(4); rps.append(rp)
                    cnt=nv-order if k==0 else nv
                    for _ in range(cnt): rice(g,rp)
                subs.append(('fixed%d'%order,wasted,po,rps))
            elif (t6>>5)==1:
                order=(t6&31)+1
                for _ in range(order): g.sread(eff)
                prec=g.read(4)+1; shift=g.read(5)
                coef=[g.sread(prec) for _ in range(order)]
                mt=g.read(2); po=g.read(4)
                np_=1<<po; nv=bs>>po
                rps=[]
                for k in range(np_):
                    rp=g.read(4); rps.append(rp)
                    cnt=nv-order if k==0 else nv
                    for _ in range(cnt): rice(g,rp)
                subs.append(('lpc%d'%order,wasted,prec,shift,po,rps,coef))
            else:
                raise Exception('t6=%d'%t6)
        res.append((bs,chc,subs))
        g.read(16); g.align(); p=g.pos
    return (sr,ch,bps,tot),res
