    wav=sys.argv[1]
    print('default:')
    f=encode(wav,'/tmp/an.flac')
    m,r=params(f)
    print('  meta',m,'nframes',len(r))
    for fr in r[:3]: print('   ',fr[0],fr[1],[s[:6] if len(s)>6 else s for s in fr[2]])
