                elif s[0]=='verb': desc.append('verb')
                elif s[0].startswith('fixed'): desc.append(s[0]+'(po=%d,rp=%s)'%(s[2],s[3]))
                else: desc.append('%s(prec=%d,sh=%d,po=%d,rp=%s,coef=%s)'%(s[0],s[2],s[3],s[4],s[5],s[6]))
        print('  lvl %2d size=%5d %s'%(lvl,d,' | '.join(desc[:2])))
