import sys,math; sys.path.insert(0,'/tmp')
from lpc import getpcm,autoc,schur_ref,ref_to_lpc
s=getpcm('/workspace/assets/flac_rt.wav'); n=len(s)
def W(name):
    if name=='none': return lambda x:x
    if name=='welch_ff':
        def f(x):
            m=len(x); w=[0.0]*m; n2=m>>1
            for i in range(n2):
                tmp=(i+1)/(m+1)
                w[i]=x[i]*(1.0-tmp*tmp); w[m-1-i]=x[m-1-i]*(1.0-tmp*tmp)
            if m&1: w[n2]=x[n2]
            return w
        return f
    if name=='hann_ff':
        def f(x):
            m=len(x); w=[0.0]*m; n2=m>>1
            for i in range(n2):
                v=0.5-0.5*math.cos(2*math.pi*(i+1)/(m+1))
                w[i]=x[i]*v; w[m-1-i]=x[m-1-i]*v
            if m&1: w[n2]=x[n2]
            return w
        return f
    if name=='welch_c':
        def f(x):
            m=len(x); c=(m-1)/2.0
            return [x[i]*(1-((i-c)/c)**2) for i in range(m)]
        return f
    if name=='hann_c':
        def f(x):
            m=len(x)
            return [x[i]*(0.5-0.5*math.cos(2*math.pi*i/m)) for i in range(m)]
        return f
target=[14864,-853,-5438,-2948,-1339,2549,4112,-2783]
def energy(a,s):
    o=len(a); acc=0.0
    for i in range(o,len(s)):
        e=s[i]-sum(a[k]*s[i-1-k] for k in range(o)); acc+=e*e
    return acc
e0=sum(x*x for x in s)
for name in ['none','welch_ff','hann_ff','welch_c','hann_c']:
    x=W(name)(s)
    r=autoc(x,8)
    k,E=schur_ref(r,8)
    a=ref_to_lpc(k,8)
    got=[round(v*8192) for v in a]
    ee=energy(a,s)/e0
    print('%-9s a=%s E/E0=%.3g %s'%(name,got,ee,'OK' if got==target else ''))
print('target    ',target)
EOF"}

