import os,sys
# simple LZ77: token = (flag byte, ...) ; we use: literal byte, or (offset,len) 3-byte
def compress(data):
    out=bytearray(); pos=0; n=len(data)
    W=4096; MAXL=255
    litbuf=bytearray()
    def flush():
        if litbuf:
            out.append(0); out.extend(litbuf); litbuf.clear()
    while pos<n:
        best=(0,0)
        start=max(0,pos-W)
        # search
        limit=min(MAXL, n-pos)
        if limit>=3:
            # use dict of hashes
            i=start
            while i<pos:
                l=0
                while l<limit and data[i+l]==data[pos+l]: l+=1
                if l>best[0]: best=(l,pos-i)
                i+=1
        if best[0]>=4:
            flush()
            out.append(1)
            off=best[1]; ln=best[0]
            out.append(off&0xff); out.append((off>>8)&0xff); out.append(ln)
            pos+=ln
        else:
            litbuf.append(data[pos]); pos+=1
            if len(litbuf)==255: flush()
    flush()
    return bytes(out)
def decompress(data):
    out=bytearray(); i=0; n=len(data)
    while i<n:
        f=data[i]; i+=1
        if f==0:
            ln=data[i]; i+=1
            out.extend(data[i:i+ln]); i+=ln
        else:
            off=data[i]|(data[i+1]<<8); ln=data[i+2]; i+=3
            p=len(out)-off
            for k in range(ln): out.append(out[p+k])
    return bytes(out)
if __name__=='__main__':
    mode=sys.argv[1]
    if mode=='c':
        arr=[]
        total=0
        for f in sys.argv[2:]:
            data=open(f,'rb').read()
            c=compress(data)
            total+=len(c)
            arr.append((os.path.basename(f),len(data),c))
        print('total compressed',total)
        with open('/workspace/src/lists_blob.h','w') as fh:
            fh.write('/* generated */\nstatic const unsigned char lists_blob[] = {\n')
            blob=bytearray(); idx=[]
            for name,orig,c in arr:
                idx.append((name,orig,len(blob),len(c)))
                blob.extend(c)
            for i in range(0,len(blob),16):
                fh.write(','.join('0x%02x'%b for b in blob[i:i+16])+',\n')
            fh.write('};\n')
            fh.write('typedef struct { const char *name; int origlen; int off; int len; } ListEntry;\n')
            fh.write('static const ListEntry lists_table[] = {\n')
            for name,orig,off,l in idx:
                fh.write('{"%s",%d,%d,%d},\n'%(name,orig,off,l))
            fh.write('{0,0,0,0}\n};\n')
PYEOF
