#include "ffm.h"

int ff_log_level = AV_LOG_INFO;
static const char *log_prefix = NULL;

void ff_set_log_prefix(const char *p){ log_prefix = p; }

void ff_vlog(int level, const char *fmt, va_list ap)
{
    if (level > ff_log_level) return;
    if (log_prefix && *log_prefix) fprintf(stderr, "%s ", log_prefix);
    vfprintf(stderr, fmt, ap);
}

void ff_log(int level, const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    ff_vlog(level, fmt, ap);
    va_end(ap);
