#include "codec.h"

void br_init(BitRd *b, const uint8_t *d, int size){ b->d=d; b->pos=0; b->bit=0; b->size=size; }

uint32_t br_bits(BitRd *b, int n)
{
    uint32_t v = 0;
    int i;
    for (i = 0; i < n; i++) {
        int byte = b->pos, bit = b->bit;
        if (byte >= b->size) { b->pos = b->size; b->bit = 0; return v; }
        v = (v << 1) | ((b->d[byte] >> (7 - bit)) & 1);
        if (++b->bit == 8) { b->bit = 0; b->pos++; }
    }
    return v;
}

int32_t br_sbits(BitRd *b, int n)
{
    uint32_t v = br_bits(b, n);
    if (n <= 0) return 0;
    if (v & (1u << (n - 1))) return (int32_t)(v - (1u << n));
    return (int32_t)v;
}

uint32_t br_unary(BitRd *b)
{
    uint32_t v = 0;
    while (br_bits(b, 1) == 0) { v++; if (v > (1u<<24)) return v; }
    return v;
}

void br_align(BitRd *b){ if (b->bit) { b->bit = 0; b->pos++; } }

void bw_init(BitWr *b, uint8_t *d, int cap){ b->d=d; b->pos=0; b->bit=0; b->cap=cap; }

void bw_bits(BitWr *b, uint32_t v, int n)
{
    int i;
    for (i = n - 1; i >= 0; i--) {
        uint8_t bit = (uint8_t)((v >> i) & 1);
        b->d[b->pos] = (uint8_t)((b->d[b->pos] << 1) | bit);
        if (++b->bit == 8) { b->bit = 0; b->pos++; b->d[b->pos] = 0; }
    }
}

void bw_align(BitWr *b)
{
    while (b->bit) bw_bits(b, 0, 1);
}

int bw_bytepos(BitWr *b){ return b->pos; }
EOF
echo ok"}

