{"command": "cat > /workspace/src/flac.c <<'EOF'
/* FLAC decoder / encoder (reverse engineered) */
#include "codec.h"

/* ------------------------------------------------------------------ probe */
int flac_probe(const uint8_t *buf, int len)
{
    if (len < 4) return 0;
    return buf[0]=='f' && buf[1]=='L' && buf[2]=='a' && buf[3]=='C';
}

static int64_t rd_be(const uint8_t *p, int n)
{
    int64_t v = 0; int i;
    for (i = 0; i < n; i++) v = (v << 8) | p[i];
    return v;
}

/* read metadata; leaves the stream positioned at the first audio frame.
 * Returns 0 on success. */
int flac_read_header(FILE *f, MediaInfo *mi, unsigned char **vorbis_comment)
{
    uint8_t hdr[4];
    int last = 0, have_si = 0;
    uint8_t si[34];
    if (fread(hdr,1,4,f) != 4) return AVERROR_EIO;
    if (memcmp(hdr,"fLaC",4)) return AVERROR_EINVAL;
    memset(mi, 0, sizeof(*mi));
    mi->total_samples = -1;
    while (!last) {
        uint8_t bh[4];
        int type, len;
        if (fread(bh,1,4,f) != 4) return AVERROR_EIO;
        type = bh[0] & 0x7f;
        last = bh[0] >> 7;
        len = (int)((bh[1]<<16)|(bh[2]<<8)|bh[3]);
        if (type == 0) {
            if (len < 34) return AVERROR_EINVAL;
            if (fread(si,1,34,f) != 34) return AVERROR_EIO;
            if (len > 34) fseek(f, len-34, SEEK_CUR);
            have_si = 1;
        } else if (type == 4) {
            uint8_t *b = (uint8_t*)malloc(len);
            if (!b) return AVERROR_NOMEM;
            if (fread(b,1,len,f) != (size_t)len) { free(b); return AVERROR_EIO; }
            if (vorbis_comment) {
                if (*vorbis_comment) free(*vorbis_comment);
                *vorbis_comment = b;
            } else free(b);
        } else {
            if (len && fseek(f, len, SEEK_CUR)) return AVERROR_EIO;
        }
    }
    if (!have_si) return AVERROR_EINVAL;
    mi->sample_rate = (int)((rd_be(si+10,3) >> 4) & 0xFFFFF);
    mi->channels    = (int)(((rd_be(si+13,1) >> 4) & 0x07) + 1);
    mi->bits        = (int)(((rd_be(si+13,1) >> 1) & 0x1F) + 1);
    {
        uint64_t tot = (uint64_t)rd_be(si+13,5) & ((1ULL<<36)-1);
        mi->total_samples = tot;
    }
    mi->duration_us = mi->total_samples > 0 && mi->sample_rate
        ? (int64_t)(mi->total_samples * 1000000.0 / mi->sample_rate) : 0;
    mi->encoder_tag = NULL;
    return 0;
}

/* ------------------------------------------------------------------ decode */
static void lpc_predict(int32_t *out, const int32_t *coef, int order, int shift,
                        const int32_t *res, int nres)
{
    int i, j;
    for (i = 0; i < nres; i++) {
        int64_t acc = 0;
        for (j = 0; j < order; j++) acc += (int64_t)coef[j] * out[i - 1 - j];
        out[i] = res[i] + (int32_t)(acc >> shift);
    }
}

static void fixed_predictor(int order, const int32_t *hist, int32_t *res, int n)
{
    int i;
    for (i = 0; i < n; i++) {
        int32_t acc = 0;
        switch (order) {
        case 0: acc = 0; break;
        case 1: acc = hist[i-1]; break;
        case 2: acc = 2*hist[i-1] - hist[i-2]; break;
        case 3: acc = 3*hist[i-1] - 3*hist[i-2] + hist[i-3]; break;
        default: acc = 4*hist[i-1] - 6*hist[i-2] + 4*hist[i-3] - hist[i-4]; break;
        }
        res[i] += acc;
    }
}

static int read_residuals(BitRd *g, int bs, int order, int32_t *out)
{
    int mt, po, np, nv, i, j, cnt = 0;
    mt = (int)br_bits(g, 2);
    if (mt != 0) return AVERROR_EINVAL;
    po = (int)br_bits(g, 4);
    np = 1 << po;
    nv = bs >> po;
    for (i = 0; i < np; i++) {
        int rp = (int)br_bits(g, 4);
        int n = (i == 0) ? nv - order : nv;
        for (j = 0; j < n; j++) {
            uint32_t q = br_unary(g);
            uint32_t r = rp ? br_bits(g, rp) : 0;
            uint32_t u = (q << rp) | r;
            int32_t val;
            if (u & 1) val = -((int32_t)(u >> 1) + 1);
            else val = (int32_t)(u >> 1);
            out[cnt++] = val;
        }
    }
    return cnt;
}

/* decode a single frame from a buffered reader (which must be positioned at the
 * sync code).  Returns the number of samples decoded (>=0) or <0 on error. */
int flac_decode_frame(FILE *f, BitRd *pending, int channels, int bits,
                      int32_t *out, int max_samples, int *out_channels, int *frame_len)
{
    uint8_t hdr[64];
    int hlen = 0, i, ch, bs = 0, bsc, src, chc, szc, strat;
    int sz, nsub, wasted_all = 0;
    uint8_t fcrc;
    uint16_t ecrc;
    int32_t *sub[MAXCH_];
    int subsz[MAXCH_];
    int wasted[MAXCH_];
    int ret;
    BitRd g;
    uint8_t *buf = NULL;
    int cap;
    int64_t start;

    /* gather bytes until we can parse the header */
    if (pending->pos < pending->size) {
        /* buffered data available */
    } else {
        pending->pos = pending->size = 0; pending->bit = 0;
    }
    /* read progressively */
    cap = 64;
    buf = (uint8_t*)malloc(cap);
    if (!buf) return AVERROR_NOMEM;
    {
        int got = 0;
        if (pending->size > pending->pos) {
            got = pending->size - pending->pos;
            memcpy(buf, pending->d + pending->pos, got);
            pending->pos = pending->size = 0; pending->bit = 0;
        }
        while (got < 16) {
            int c = fgetc(f);
            if (c == EOF) { free(buf); return 0; }
            buf[got++] = (uint8_t)c;
        }
        /* parse header to find its length */
        {
            uint8_t tmp[64];
            memcpy(tmp, buf, 16);
            BitRd t; br_init(&t, tmp, 16);
            br_bits(&t, 14);
            int res1 = (int)br_bits(&t,1);
            strat = (int)br_bits(&t,1);
            bsc = (int)br_bits(&t,4);
            src = (int)br_bits(&t,4);
            chc = (int)br_bits(&t,4);
            szc = (int)br_bits(&t,3);
            br_bits(&t,1);
            (void)res1;
            hlen = t.pos;              /* bytes consumed so far */
            if (bsc == 6) hlen += 1;
            else if (bsc == 7) hlen += 2;
            if (src == 12) hlen += 1;
            else if (src == 13 || src == 14) hlen += 2;
            hlen += 1; /* crc8 */
            if (hlen > cap) { cap = hlen + 16; buf = (uint8_t*)realloc(buf, cap); }
        }
        while (got < hlen) {
            int c = fgetc(f);
            if (c == EOF) { free(buf); return AVERROR_EIO; }
            buf[got++] = (uint8_t)c;
        }
        if (buf[0] != 0xff || (buf[1] & 0xfc) != 0xf8) { free(buf); return AVERROR_EINVAL; }
        fcrc = buf[hlen-1];
        if (ff_crc8(buf, hlen-1) != fcrc) { free(buf); return AVERROR_EINVAL; }
    }
    /* block size */
    if (bsc == 1) bs = 192;
    else if (bsc >= 2 && bsc <= 5) bs = 576 << (bsc - 2);
    else if (bsc >= 8 && bsc <= 15) bs = 256 << (bsc - 8);
    {
        BitRd t; br_init(&t, buf, hlen);
        br_bits(&t, 14); br_bits(&t,1); strat = (int)br_bits(&t,1);
        bsc = (int)br_bits(&t,4); src = (int)br_bits(&t,4);
        chc = (int)br_bits(&t,4); szc = (int)br_bits(&t,3); br_bits(&t,1);
        br_bits(&t, 8); /* frame/sample number (utf8 handled below) */
        /* NOTE: utf-8 length handled by re-parsing */
    }
    /* reparse properly with utf-8 frame number */
    {
        BitRd t; br_init(&t, buf, hlen);
        br_bits(&t, 14); br_bits(&t,1); strat = (int)br_bits(&t,1);
        bsc = (int)br_bits(&t,4); src = (int)br_bits(&t,4);
        chc = (int)br_bits(&t,4); szc = (int)br_bits(&t,3); br_bits(&t,1);
        /* utf-8 coded number */
        {
            uint32_t v = br_bits(&t, 8);
            if (v >= 0xC0) { int extra = (v >= 0xF0) ? 3 : (v >= 0xE0 ? 2 : 1);
                while (extra--) br_bits(&t, 6); }
        }
        if (bsc == 6) bs = (int)br_bits(&t,8) + 1;
        else if (bsc == 7) bs = (int)br_bits(&t,16) + 1;
        else if (bsc == 1) bs = 192;
        else if (bsc >= 2 && bsc <= 5) bs = 576 << (bsc - 2);
        else if (bsc >= 8 && bsc <= 15) bs = 256 << (bsc - 8);
        if (src == 12) br_bits(&t,8);
        else if (src == 13 || src == 14) br_bits(&t,16);
    }
    (void)hlen;
    if (bs <= 0 || bs > 65535) { free(buf); return AVERROR_EINVAL; }
    sz = (szc == 0) ? bits : (szc == 1 ? 8 : szc == 2 ? 12 : szc == 3 ? bits :
         szc == 4 ? 16 : szc == 5 ? 20 : szc == 6 ? 24 : 32);
    nsub = (chc < 8) ? chc + 1 : ((chc == 11) ? 4 : 2);
    if (nsub > channels) nsub = channels;
    *out_channels = nsub;
    /* read the rest of the frame: we must know its length.  Parse subframes
     * from the buffered header bytes plus more data read on demand. */
    /* We buffer the whole frame by scanning: parse incrementally. */
    {
        int need = hlen;  /* we will grow buf as needed */
        /* first make sure we have hlen bytes already (done) */
        g.d = buf; g.pos = hlen; g.bit = 0; g.size = got;
        /* ensure enough bytes are present while parsing */
        int total_bits_estimate = 0;
        (void)total_bits_estimate;
        for (ch = 0; ch < nsub; ch++) {
            int t6, wb, w = 0, eff, t6v;
            sub[ch] = NULL;
            while (g.pos + 16 >= g.size) {
                int c = fgetc(f);
                if (c == EOF) { ret = AVERROR_EIO; goto fail; }
                if (g.size >= cap) { cap *= 2; buf = (uint8_t*)realloc(buf, cap); g.d = buf; }
                buf[g.size++] = (uint8_t)c;
            }
            br_bits(&g, 1);
            t6 = (int)br_bits(&g, 6);
            wb = (int)br_bits(&g, 1);
            if (wb) {
                uint32_t u = br_unary(&g);
                w = (int)u + 1;
            }
            eff = sz - w;
            wasted[ch] = w;
            if (t6 == 0) {
                int32_t v = br_sbits(&g, eff);
