/* FLAC decoder / encoder (reverse engineered) */
#include "codec.h"

/* ------------------------------------------------------------------ probe */
int flac_probe(const uint8_t *buf, int len)
{
    if (len < 4) return 0;
    return buf[0]=='f' && buf[1]=='L' && buf[2]=='a' && buf[3]=='C';
}

static int64_t rd_be(const uint8_t *p, int n)
{
    int64_t v = 0; int i;
    for (i = 0; i < n; i++) v = (v << 8) | p[i];
    return v;
}

/* read metadata; leaves the stream positioned at the first audio frame.
 * Returns 0 on success. */
int flac_read_header(FILE *f, MediaInfo *mi, unsigned char **vorbis_comment)
{
    uint8_t hdr[4];
    int last = 0, have_si = 0;
    uint8_t si[34];
    if (fread(hdr,1,4,f) != 4) return AVERROR_EIO;
    if (memcmp(hdr,"fLaC",4)) return AVERROR_EINVAL;
    memset(mi, 0, sizeof(*mi));
    mi->total_samples = -1;
    while (!last) {
        uint8_t bh[4];
        int type, len;
        if (fread(bh,1,4,f) != 4) return AVERROR_EIO;
        type = bh[0] & 0x7f;
        last = bh[0] >> 7;
        len = (int)((bh[1]<<16)|(bh[2]<<8)|bh[3]);
        if (type == 0) {
            if (len < 34) return AVERROR_EINVAL;
            if (fread(si,1,34,f) != 34) return AVERROR_EIO;
            if (len > 34) fseek(f, len-34, SEEK_CUR);
            have_si = 1;
        } else if (type == 4) {
            uint8_t *b = (uint8_t*)malloc(len);
            if (!b) return AVERROR_NOMEM;
            if (fread(b,1,len,f) != (size_t)len) { free(b); return AVERROR_EIO; }
            if (vorbis_comment) {
                if (*vorbis_comment) free(*vorbis_comment);
                *vorbis_comment = b;
            } else free(b);
        } else {
            if (len && fseek(f, len, SEEK_CUR)) return AVERROR_EIO;
        }
    }
    if (!have_si) return AVERROR_EINVAL;
    mi->sample_rate = (int)((rd_be(si+10,3) >> 4) & 0xFFFFF);
    mi->channels    = (int)(((rd_be(si+13,1) >> 4) & 0x07) + 1);
    mi->bits        = (int)(((rd_be(si+13,1) >> 1) & 0x1F) + 1);
    {
        uint64_t tot = (uint64_t)rd_be(si+13,5) & ((1ULL<<36)-1);
        mi->total_samples = tot;
    }
    mi->duration_us = mi->total_samples > 0 && mi->sample_rate
        ? (int64_t)(mi->total_samples * 1000000.0 / mi->sample_rate) : 0;
    mi->encoder_tag = NULL;
    return 0;
}

/* ------------------------------------------------------------------ decode */
static void lpc_predict(int32_t *out, const int32_t *coef, int order, int shift,
                        const int32_t *res, int nres)
{
    int i, j;
    for (i = 0; i < nres; i++) {
        int64_t acc = 0;
        for (j = 0; j < order; j++) acc += (int64_t)coef[j] * out[i - 1 - j];
        out[i] = res[i] + (int32_t)(acc >> shift);
    }
}

static void fixed_predictor(int order, const int32_t *hist, int32_t *res, int n)
{
    int i;
    for (i = 0; i < n; i++) {
        int32_t acc = 0;
        switch (order) {
        case 0: acc = 0; break;
        case 1: acc = hist[i-1]; break;
        case 2: acc = 2*hist[i-1] - hist[i-2]; break;
        case 3: acc = 3*hist[i-1] - 3*hist[i-2] + hist[i-3]; break;
        default: acc = 4*hist[i-1] - 6*hist[i-2] + 4*hist[i-3] - hist[i-4]; break;
        }
        res[i] += acc;
    }
}

static int read_residuals(BitRd *g, int bs, int order, int32_t *out)
{
    int mt, po, np, nv, i, j, cnt = 0;
    mt = (int)br_bits(g, 2);
    if (mt != 0) return AVERROR_EINVAL;
    po = (int)br_bits(g, 4);
    np = 1 << po;
    nv = bs >> po;
    for (i = 0; i < np; i++) {
        int rp = (int)br_bits(g, 4);
        int n = (i == 0) ? nv - order : nv;
        for (j = 0; j < n; j++) {
            uint32_t q = br_unary(g);
            uint32_t r = rp ? br_bits(g, rp) : 0;
            uint32_t u = (q << rp) | r;
            int32_t val;
            if (u & 1) val = -((int32_t)(u >> 1) + 1);
            else val = (int32_t)(u >> 1);
            out[cnt++] = val;
        }
    }
    return cnt;
}

