                for (i = 0; i < order; i++) s[i] = br_sbits(&g, eff);
                prec = (int)br_bits(&g, 4) + 1;
                shift = (int)br_bits(&g, 5);
                coef = (int32_t*)malloc(sizeof(int32_t)*order);
                if (!coef) { free(s); ret = AVERROR_NOMEM; goto fail; }
                for (i = 0; i < order; i++) coef[i] = br_sbits(&g, prec);
                res = (int32_t*)malloc(sizeof(int32_t)*bs);
                if (!res) { free(s); free(coef); ret = AVERROR_NOMEM; goto fail; }
                nres = read_residuals(&g, bs, order, res);
                if (nres < 0) { free(s); free(coef); free(res); ret = nres; goto fail; }
                lpc_predict(s + order, coef, order, shift, res, nres);
                free(res); free(coef);
