/* --------------------------------------------------------------- decoding */
static int read_residuals(BitRd *g, int bs, int order, int32_t *out)
{
    int mt, po, np, nv, i, j, cnt = 0;
    mt = (int)br_bits(g, 2);
    if (mt != 0) return AVERROR_EINVAL;
    po = (int)br_bits(g, 4);
    np = 1 << po;
    nv = bs >> po;
    for (i = 0; i < np; i++) {
        int rp = (int)br_bits(g, 4);
        int n = (i == 0) ? nv - order : nv;
        for (j = 0; j < n; j++) {
            uint32_t q = br_unary(g);
            uint32_t r = rp ? br_bits(g, rp) : 0;
            uint32_t u = (q << rp) | r;
            int32_t val;
            if (u & 1) val = -((int32_t)(u >> 1) + 1);
            else val = (int32_t)(u >> 1);
            if (cnt < bs) out[cnt++] = val;
        }
    }
    return cnt;
}

static void fixed_residual_add(int order, int32_t *res, int n)
{
    int i;
    for (i = 0; i < n; i++) {
        int32_t acc = 0;
        switch (order) {
        case 1: acc = res[i-1]; break;
        case 2: acc = 2*res[i-1] - res[i-2]; break;
        case 3: acc = 3*res[i-1] - 3*res[i-2] + res[i-3]; break;
        case 4: acc = 4*res[i-1] - 6*res[i-2] + 4*res[i-3] - res[i-4]; break;
