    for (i = 0; i < sf->order; i++)
        bw_bits(bw, (uint32_t)(s0[i] >> w) & ((1u << eff) - 1), eff);
    if (sf->type == 3) {
        bw_bits(bw, sf->prec - 1, 4);
        bw_bits(bw, sf->shift, 5);
        for (i = 0; i < sf->order; i++)
            bw_bits(bw, (uint32_t)sf->coef[i] & ((1u << sf->prec) - 1), sf->prec);
    }
    /* residuals */
    {
        int32_t *res = (int32_t*)malloc(sizeof(int32_t)*n);
        int o = sf->order;
        if (!res) return;
        if (sf->type == 2) fixed_residual(s0, n, o, res);
        else lpc_residual(s0, n, sf->coef, o, sf->shift, res);
        bw_bits(bw, 0, 2);
        bw_bits(bw, sf->po, 4);
        {
            int np = 1 << sf->po, nv = (n - o) >> sf->po, k;
            for (k = 0; k < np; k++) {
                int rp = best_rice_param(res + k*nv, nv);
                int j;
                bw_bits(bw, rp, 4);
                for (j = 0; j < nv; j++) {
                    uint32_t u = zigzag(res[k*nv + j]);
                    uint32_t q = u >> rp, r = u & ((1u << rp) - 1);
                    int t;
                    for (t = 0; t < (int)q; t++) bw_bits(bw, 0, 1);
                    bw_bits(bw, 1, 1);
                    if (rp) bw_bits(bw, r, rp);
                }
            }
        }
        free(res);
    }
}

static int bs_code(int bs, int *extra_len, int *extra_val)
{
    *extra_len = 0; *extra_val = 0;
    if (bs == 192) return 1;
    if (bs == 576) return 2;
    if (bs == 1152) return 3;
    if (bs == 2304) return 4;
    if (bs == 4608) return 5;
    if (bs == 256) return 8;
    if (bs == 512) return 9;
    if (bs == 1024) return 10;
    if (bs == 2048) return 11;
    if (bs == 4096) return 12;
    if (bs == 8192) return 13;
    if (bs == 16384) return 14;
    if (bs == 32768) return 15;
    if (bs <= 256) { *extra_len = 1; *extra_val = bs - 1; return 6; }
    *extra_len = 2; *extra_val = bs - 1; return 7;
}

static int sr_code(int sr, int *extra_len, int *extra_val)
{
    *extra_len = 0; *extra_val = 0;
    switch (sr) {
    case 88200: return 1; case 176400: return 2; case 192000: return 3;
    case 8000: return 4; case 16000: return 5; case 22050: return 6;
    case 24000: return 7; case 32000: return 8; case 44100: return 9;
    case 48000: return 10; case 96000: return 11;
    }
    if (sr % 1000 == 0 && sr/1000 <= 255) { *extra_len = 1; *extra_val = sr/1000; return 12; }
    if (sr <= 65535) { *extra_len = 2; *extra_val = sr; return 13; }
    if (sr % 10 == 0 && sr/10 <= 65535) { *extra_len = 2; *extra_val = sr/10; return 14; }
    return 13;
}

static int sz_code(int bits)
{
    switch (bits) {
    case 8: return 1; case 12: return 2; case 16: return 4;
    case 20: return 5; case 24: return 6; case 32: return 7;
    }
    return 0;
}

static void put_utf8(BitWr *bw, uint32_t v)
{
    if (v < 0x80) { bw_bits(bw, v, 8); return; }
    if (v < 0x800) { bw_bits(bw, 0xC0 | (v >> 6), 8); bw_bits(bw, 0x80 | (v & 0x3f), 8); return; }
    if (v < 0x10000) { bw_bits(bw, 0xE0 | (v >> 12), 8); bw_bits(bw, 0x80 | ((v >> 6) & 0x3f), 8);
