/* FLAC encoder (reverse engineered) */
#include "codec.h"

/* ---------------------------------------------------------- LPC analysis */
static void apply_welch_sq(const int32_t *s, int n, double *x)
{
    int i;
    for (i = 0; i < n; i++) {
        double t = fabs(2.0*i - n + 1.0) / (double)(n + 1);
        double w = (1.0 - t) * (1.0 - t);
        x[i] = (double)s[i] * w;
    }
}

static void compute_autocorr(const double *x, int len, int lag, double *autoc)
{
    int i, j;
    for (j = 0; j <= lag; j++) {
        double sum = 0.0;
        for (i = j; i < len; i++) sum += x[i] * x[i-j];
        autoc[j] = sum;
    }
}

static int levinson(const double *r, int order, double *a, double *err_out)
{
    int m, k;
    double E;
    if (r[0] <= 0) return -1;
    for (k = 0; k <= order; k++) a[k] = 0.0;
    a[1] = r[1] / r[0];
    E = r[0] - a[1] * r[1];
    if (E <= 0) return -1;
    for (m = 2; m <= order; m++) {
        double acc = r[m], km;
        double anew[MAXCH_ + 2];
        for (k = 1; k < m; k++) acc -= a[k] * r[m-k];
        km = acc / E;
        for (k = 0; k <= order; k++) anew[k] = 0.0;
        for (k = 1; k < m; k++) anew[k] = a[k] - km * a[m-k];
        anew[m] = km;
        for (k = 0; k <= order; k++) a[k] = anew[k];
        E -= km * acc;
        if (E <= 0) return -1;
    }
    if (err_out) *err_out = E;
    return 0;
}

static void lpc_coefs(const int32_t *s, int n, int order, int precision,
                      int32_t *coef, int *shift)
{
    double *x = (double*)malloc(sizeof(double)*n);
    double r[MAXCH_+1];
    double a[MAXCH_+2];
    int i, sh;
    double mx = 0;
    if (!x) { for (i=0;i<order;i++) coef[i]=0; *shift=0; return; }
    apply_welch_sq(s, n, x);
    compute_autocorr(x, n, order, r);
    free(x);
    if (levinson(r, order, a, NULL) < 0) {
        for (i = 0; i < order; i++) coef[i] = 0;
        *shift = 0;
        return;
    }
    for (i = 1; i <= order; i++) if (fabs(a[i]) > mx) mx = fabs(a[i]);
    if (mx <= 0) { for (i=0;i<order;i++) coef[i]=0; *shift = precision>15?15:precision; *shift = 15; return; }
    sh = 0;
    while (sh < 15 && mx * (double)(1u << (sh + 1)) < 16383.5) sh++;
    for (i = 0; i < order; i++) {
        double v = a[i+1] * (double)(1u << sh);
        int32_t q = (int32_t)lrint(v);
        if (q > 16383) q = 16383;
        if (q < -16383) q = -16383;
        coef[i] = q;
    }
    *shift = sh;
}

/* ------------------------------------------------------------- prediction */
static void lpc_residual(const int32_t *s, int n, const int32_t *coef, int order,
                         int shift, int32_t *res)
{
    int i, j;
    for (i = order; i < n; i++) {
        int64_t acc = 0;
        for (j = 0; j < order; j++) acc += (int64_t)coef[j] * s[i-1-j];
        res[i-order] = s[i] - (int32_t)(acc >> shift);
    }
}

static void fixed_residual(const int32_t *s, int n, int order, int32_t *res)
{
    int i;
    for (i = order; i < n; i++) {
        int64_t acc = 0;
        switch (order) {
        case 0: acc = 0; break;
        case 1: acc = s[i-1]; break;
        case 2: acc = 2*(int64_t)s[i-1] - s[i-2]; break;
        case 3: acc = 3*(int64_t)s[i-1] - 3*(int64_t)s[i-2] + s[i-3]; break;
        default: acc = 4*(int64_t)s[i-1] - 6*(int64_t)s[i-2] + 4*(int64_t)s[i-3] - s[i-4]; break;
        }
        res[i-order] = s[i] - (int32_t)acc;
    }
}

/* --------------------------------------------------------------- rice */
static inline uint32_t zigzag(int32_t v)
{
    return (v >= 0) ? (uint32_t)(v << 1) : (uint32_t)((-(int64_t)v) * 2 - 1);
}

static int64_t rice_bits(const int32_t *res, int n, int rp)
{
    int64_t bits = (int64_t)n * (rp + 1);
    int i;
    for (i = 0; i < n; i++) bits += zigzag(res[i]) >> rp;
    return bits;
}

static int best_rice_param(const int32_t *res, int n)
{
    int rp, best = 0;
    int64_t bestb = 0;
    for (rp = 0; rp < 15; rp++) {
        int64_t b = rice_bits(res, n, rp);
        if (rp == 0 || b < bestb) { bestb = b; best = rp; }
    }
    return best;
}

/* Returns total bits for the residual section (method+po+rps+values) and
 * fills rps[].  Returns -1 if impossible. */
static int64_t residual_cost(const int32_t *res, int n, int order, int po, int *rps)
{
    int np = 1 << po, nv, i;
    int64_t tot = 2 + 4;
    if (po > 15) return -1;
    if (n % (1 << po)) return -1;
    nv = n >> po;
    if (nv <= order) return -1;
    for (i = 0; i < np; i++) {
        int rp = best_rice_param(res + i*nv, nv);
        tot += 4 + rice_bits(res + i*nv, nv, rp);
        if (rps) rps[i] = rp;
    }
    return tot;
}

static int64_t best_residual(const int32_t *res, int n, int order,
                             int min_part, int max_part, int *po_out, int *rps_out)
{
    int po;
    int64_t best = -1;
    int bestpo = 0;
    for (po = min_part; po <= max_part; po++) {
        int64_t t = residual_cost(res, n, order, po, rps_out ? rps_out + (po<<0) : NULL);
        if (t < 0) continue;
        /* rps buffer indexing handled by caller passing scratch */
        if (best < 0 || t < best) { best = t; bestpo = po; }
    }
    if (best >= 0 && po_out) *po_out = bestpo;
    if (best >= 0 && rps_out) residual_cost(res, n, order, bestpo, rps_out);
    return best;
}

/* ------------------------------------------------------- subframe costing */
typedef struct {
    int type;       /* 0 const, 1 verbatim, 2 fixed, 3 lpc */
    int order;
    int wasted;
    int prec, shift;
    int32_t coef[MAXCH_];
    int po;
    int rps[1 << 8];
    int64_t bits;   /* total subframe bits */
} SubFrame;

static int compute_wasted(const int32_t *s, int n, int bits)
{
    int w = 0, i, k;
    if (bits <= 1) return 0;
    for (k = 0; k < bits - 1; k++) {
        int all = 1;
        for (i = 0; i < n; i++) if (s[i] & (1 << k)) { all = 0; break; }
        if (!all) break;
        w++;
    }
    return w;
}

/* Evaluate all candidate subframes for one channel; returns the best in *sf */
static void eval_subframes(const int32_t *s0, int n, int bits, int max_lpc_order,
                           int min_part, int max_part, SubFrame *sf)
{
    int w = compute_wasted(s0, n, bits);
    int eff = bits - w;
    int i;
    int32_t *s = (int32_t*)malloc(sizeof(int32_t)*n);
    int32_t *res = (int32_t*)malloc(sizeof(int32_t)*n);
    SubFrame best;
    int o;
    memset(&best, 0, sizeof(best));
    best.bits = -1;
    if (!s || !res) { free(s); free(res); sf->type = 1; sf->wasted = 0;
                      sf->bits = (int64_t)n * bits + 8; return; }
    for (i = 0; i < n; i++) s[i] = s0[i] >> w;

    /* CONSTANT */
    {
        int all = 1;
        for (i = 1; i < n; i++) if (s[i] != s[0]) { all = 0; break; }
        if (all) {
            best.type = 0; best.order = 0; best.wasted = w;
            best.bits = 8 + eff;
        }
    }
    /* VERBATIM */
    {
        int64_t b = 8 + (int64_t)n * eff;
        if (best.bits < 0 || b < best.bits) {
            best.type = 1; best.order = 0; best.wasted = w; best.bits = b;
        }
    }
    /* FIXED */
    for (o = 0; o <= 4 && o < n; o++) {
        int po;
        int64_t bbest = -1; int bpo = 0;
        fixed_residual(s, n, o, res);
        for (po = min_part; po <= max_part; po++) {
            int64_t t = residual_cost(res, n - o, o, po, NULL);
            if (t < 0) continue;
            if (bbest < 0 || t < bbest) { bbest = t; bpo = po; }
        }
        if (bbest >= 0) {
            int64_t b = 8 + (int64_t)o * eff + bbest;
            if (best.bits < 0 || b < best.bits) {
                best.type = 2; best.order = o; best.wasted = w; best.po = bpo;
                best.bits = b;
            }
        }
    }
    /* LPC */
    for (o = 1; o <= max_lpc_order && o < n; o++) {
        int prec = 15, shift;
        int po;
        int64_t bbest = -1; int bpo = 0;
        lpc_coefs(s, n, o, prec, best.coef, &shift);
        lpc_residual(s, n, best.coef, o, shift, res);
        for (po = min_part; po <= max_part; po++) {
            int64_t t = residual_cost(res, n - o, o, po, NULL);
            if (t < 0) continue;
            if (bbest < 0 || t < bbest) { bbest = t; bpo = po; }
        }
        if (bbest >= 0) {
            int64_t b = 8 + (int64_t)o*eff + 4 + 5 + (int64_t)o*prec + bbest;
            if (best.bits < 0 || b < best.bits) {
                best.type = 3; best.order = o; best.wasted = w; best.prec = prec;
                best.shift = shift; best.po = bpo; best.bits = b;
                for (i = 0; i < o; i++) best.coef[i] = best.coef[i];
            }
        }
    }
    *sf = best;
    free(s); free(res);
}

/* ---------------------------------------------------------------- writing */
static void write_subframe(BitWr *bw, const int32_t *s0, int n, int bits,
                           const SubFrame *sf)
{
    int w = sf->wasted, eff = bits - w;
    int i;
    bw_bits(bw, 0, 1);
    if (sf->type == 0) bw_bits(bw, 0, 6);
    else if (sf->type == 1) bw_bits(bw, 1, 6);
    else if (sf->type == 2) bw_bits(bw, 0x08 + sf->order, 6);
    else bw_bits(bw, 0x20 + sf->order - 1, 6);
    if (w) { bw_bits(bw, 1, 1); for (i = 0; i < w - 1; i++) bw_bits(bw, 0, 1); bw_bits(bw, 1, 1); }
    else bw_bits(bw, 0, 1);

    if (sf->type == 0) {
        bw_bits(bw, (uint32_t)(s0[0] >> w) & ((1u << eff) - 1), eff);
        return;
    }
    if (sf->type == 1) {
        for (i = 0; i < n; i++) bw_bits(bw, (uint32_t)(s0[i] >> w) & ((1u << eff) - 1), eff);
        return;
    }
    /* warm-up samples */
    for (i = 0; i < sf->order; i++)
        bw_bits(bw, (uint32_t)(s0[i] >> w) & ((1u << eff) - 1), eff);
    if (sf->type == 3) {
        bw_bits(bw, sf->prec - 1, 4);
        bw_bits(bw, sf->shift, 5);
        for (i = 0; i < sf->order; i++)
            bw_bits(bw, (uint32_t)sf->coef[i] & ((1u << sf->prec) - 1), sf->prec);
    }
    /* residuals */
    {
        int32_t *res = (int32_t*)malloc(sizeof(int32_t)*n);
        int o = sf->order;
        if (!res) return;
        if (sf->type == 2) fixed_residual(s0, n, o, res);
        else lpc_residual(s0, n, sf->coef, o, sf->shift, res);
        bw_bits(bw, 0, 2);
        bw_bits(bw, sf->po, 4);
        {
            int np = 1 << sf->po, nv = (n - o) >> sf->po, k;
            for (k = 0; k < np; k++) {
                int rp = best_rice_param(res + k*nv, nv);
                int j;
                bw_bits(bw, rp, 4);
                for (j = 0; j < nv; j++) {
                    uint32_t u = zigzag(res[k*nv + j]);
                    uint32_t q = u >> rp, r = u & ((1u << rp) - 1);
                    int t;
                    for (t = 0; t < (int)q; t++) bw_bits(bw, 0, 1);
                    bw_bits(bw, 1, 1);
                    if (rp) bw_bits(bw, r, rp);
                }
            }
        }
        free(res);
    }
}

static int bs_code(int bs, int *extra_len, int *extra_val)
{
    *extra_len = 0; *extra_val = 0;
    if (bs == 192) return 1;
    if (bs == 576) return 2;
    if (bs == 1152) return 3;
    if (bs == 2304) return 4;
    if (bs == 4608) return 5;
    if (bs == 256) return 8;
    if (bs == 512) return 9;
    if (bs == 1024) return 10;
    if (bs == 2048) return 11;
    if (bs == 4096) return 12;
    if (bs == 8192) return 13;
    if (bs == 16384) return 14;
    if (bs == 32768) return 15;
    if (bs <= 256) { *extra_len = 1; *extra_val = bs - 1; return 6; }
    *extra_len = 2; *extra_val = bs - 1; return 7;
}

static int sr_code(int sr, int *extra_len, int *extra_val)
{
    *extra_len = 0; *extra_val = 0;
    switch (sr) {
    case 88200: return 1; case 176400: return 2; case 192000: return 3;
    case 8000: return 4; case 16000: return 5; case 22050: return 6;
    case 24000: return 7; case 32000: return 8; case 44100: return 9;
    case 48000: return 10; case 96000: return 11;
    }
    if (sr % 1000 == 0 && sr/1000 <= 255) { *extra_len = 1; *extra_val = sr/1000; return 12; }
    if (sr <= 65535) { *extra_len = 2; *extra_val = sr; return 13; }
    if (sr % 10 == 0 && sr/10 <= 65535) { *extra_len = 2; *extra_val = sr/10; return 14; }
    return 13;
}

static int sz_code(int bits)
{
    switch (bits) {
    case 8: return 1; case 12: return 2; case 16: return 4;
    case 20: return 5; case 24: return 6; case 32: return 7;
    }
    return 0;
}

static void put_utf8(BitWr *bw, uint32_t v)
{
    if (v < 0x80) { bw_bits(bw, v, 8); return; }
    if (v < 0x800) { bw_bits(bw, 0xC0 | (v >> 6), 8); bw_bits(bw, 0x80 | (v & 0x3f), 8); return; }
    if (v < 0x10000) { bw_bits(bw, 0xE0 | (v >> 12), 8); bw_bits(bw, 0x80 | ((v >> 6) & 0x3f), 8);
                       bw_bits(bw, 0x80 | (v & 0x3f), 8); return; }
    bw_bits(bw, 0xF0 | (v >> 18), 8); bw_bits(bw, 0x80 | ((v >> 12) & 0x3f), 8);
    bw_bits(bw, 0x80 | ((v >> 6) & 0x3f), 8); bw_bits(bw, 0x80 | (v & 0x3f), 8);
}

int flac_encode_stream(FILE *f, int sr, int ch, int bits, const int32_t *data,
                       int64_t nsamples, int max_lpc_order,
                       int min_part, int max_part, int64_t *out_bytes)
{
    int frame_size = 4608;
    int64_t pos = 0;
    int64_t total = 0;
    int32_t *chan[MAXCH_];
    int c;
    for (c = 0; c < ch; c++) chan[c] = (int32_t*)malloc(sizeof(int32_t)*frame_size);
    while (pos < nsamples) {
        int n = (int)((nsamples - pos > frame_size) ? frame_size : (nsamples - pos));
        int64_t k;
        uint8_t hdr[64];
        int hl = 0, extral = 0, extraval = 0, srl = 0, srval = 0;
        uint8_t *sub;
        int subcap;
        BitWr bw;
        int chc;
        int i;
        for (k = 0; k < n; k++)
            for (c = 0; c < ch; c++)
                chan[c][k] = data[(pos + k)*ch + c];
        chc = ch - 1;
        /* header */
        {
            int bsc = bs_code(n, &extral, &extraval);
            int src = sr_code(sr, &srl, &srval);
            int szc = sz_code(bits);
            BitWr hb;
            memset(hdr, 0, sizeof(hdr));
            bw_init(&hb, hdr, sizeof(hdr));
            bw_bits(&hb, 0x3ffe, 14); bw_bits(&hb, 0, 1); bw_bits(&hb, 0, 1);
            bw_bits(&hb, bsc, 4); bw_bits(&hb, src, 4);
            bw_bits(&hb, chc, 4); bw_bits(&hb, szc, 3); bw_bits(&hb, 0, 1);
            put_utf8(&hb, (uint32_t)(pos / frame_size));
            if (extral == 1) bw_bits(&hb, extraval, 8);
            else if (extral == 2) { bw_bits(&hb, (uint32_t)extraval >> 8, 8); bw_bits(&hb, extraval & 0xff, 8); }
            if (srl == 12) bw_bits(&hb, srval, 8);
            else if (srl == 13 || srl == 14) { bw_bits(&hb, (uint32_t)srval >> 8, 8); bw_bits(&hb, srval & 0xff, 8); }
            hl = bw_bytepos(&hb);
            hdr[hl++] = ff_crc8(hdr, hl);
        }
        subcap = n * ch * bits / 8 + 4096 + n * 32;
        sub = (uint8_t*)malloc(subcap);
        if (!sub) return AVERROR_NOMEM;
        memset(sub, 0, subcap);
        bw_init(&bw, sub, subcap);
        for (c = 0; c < ch; c++) {
            SubFrame sf;
            eval_subframes(chan[c], n, bits, max_lpc_order, min_part, max_part, &sf);
            write_subframe(&bw, chan[c], n, bits, &sf);
        }
        bw_align(&bw);
        {
            int sublen = bw_bytepos(&bw);
            uint8_t *frame = (uint8_t*)malloc(hl + sublen + 2);
            uint16_t crc;
            if (!frame) { free(sub); return AVERROR_NOMEM; }
            memcpy(frame, hdr, hl);
            memcpy(frame + hl, sub, sublen);
            crc = ff_crc16(frame, hl + sublen);
            frame[hl+sublen] = (uint8_t)(crc >> 8);
            frame[hl+sublen+1] = (uint8_t)(crc & 0xff);
            fwrite(frame, 1, hl + sublen + 2, f);
            total += hl + sublen + 2;
            free(frame);
        }
        free(sub);
        pos += n;
    }
    for (c = 0; c < ch; c++) free(chan[c]);
    if (out_bytes) *out_bytes = total;
    return 0;
}

void flac_write_header(FILE *f, int sr, int ch, int bits, int64_t total_samples,
                       const char *encoder)
{
    uint8_t si[38];
    uint8_t *vc;
    int vcl;
    int64_t v = ((int64_t)sr << 44) | ((int64_t)(ch-1) << 41) | ((int64_t)(bits-1) << 36) |
                (total_samples > 0 ? total_samples : 0);
    memset(si, 0, sizeof(si));
    si[0] = 0x12; si[1] = 0x00; si[2] = 0x12; si[3] = 0x00;  /* 4608 blocksize */
    /* min/max framesize unknown -> 0 */
    si[10] = (uint8_t)((v >> 40) & 0xff);
    si[11] = (uint8_t)((v >> 32) & 0xff);
    si[12] = (uint8_t)((v >> 24) & 0xff);
    si[13] = (uint8_t)((v >> 16) & 0xff);
    si[14] = (uint8_t)((v >> 8) & 0xff);
    si[15] = (uint8_t)(v & 0xff);
    /* md5 left zero */
    fwrite("fLaC", 1, 4, f);
    fputc(0x00, f); fputc(0x00, f); fputc(0x00, f); fputc(34, f);
    fwrite(si, 1, 34, f);
    /* vorbis comment */
    vcl = 4 + (int)strlen(FFM_LAVF) + 4 + 4 + (int)strlen(encoder) + 1;
    vc = (uint8_t*)calloc(1, vcl + 8);
    {
        int p = 0, l = (int)strlen(FFM_LAVF);
        vc[p++] = (uint8_t)(l >> 24); vc[p++] = (uint8_t)(l >> 16);
        vc[p++] = (uint8_t)(l >> 8); vc[p++] = (uint8_t)l;
        memcpy(vc + p, FFM_LAVF, l); p += l;
        l = 1;
        vc[p++] = 0; vc[p++] = 0; vc[p++] = 0; vc[p++] = 1;
        l = (int)strlen(encoder) + 1;
        vc[p++] = (uint8_t)(l >> 24); vc[p++] = (uint8_t)(l >> 16);
        vc[p++] = (uint8_t)(l >> 8); vc[p++] = (uint8_t)l;
        memcpy(vc + p, encoder, l - 1); p += l;
        vcl = p;
    }
    fputc(0x00, f); fputc((uint8_t)(vcl >> 16), f); fputc((uint8_t)(vcl >> 8), f); fputc((uint8_t)vcl, f);
    fwrite(vc, 1, vcl, f);
    free(vc);
    /* padding 8192, last block */
    fputc(0x81, f); fputc(0x00); fputc(0x20); fputc(0x00);
    {
        static const uint8_t zeros[256];
        int left = 8192;
        while (left > 0) { int n = left > 256 ? 256 : left; fwrite(zeros, 1, n, f); left -= n; }
    }
}
