/* WAV demuxer/muxer and raw PCM muxers */
#include "codec.h"

int wav_probe(const uint8_t *buf, int len)
{
    if (len < 12) return 0;
    if (memcmp(buf,"RIFF",4)) return 0;
    if (memcmp(buf+8,"WAVE",4)) return 0;
    return 1;
}

static uint32_t rd32(const uint8_t *p){ return p[0] | (p[1]<<8) | ((uint32_t)p[2]<<16) | ((uint32_t)p[3]<<24); }
static uint16_t rd16(const uint8_t *p){ return (uint16_t)(p[0] | (p[1]<<8)); }

int wav_read_header(FILE *f, MediaInfo *mi)
{
    uint8_t h[12], ch[8];
    int fmt = 0, channels = 0, rate = 0, bits = 0, found_data = 0;
    int64_t data_off = 0, data_len = 0;
    if (fread(h,1,12,f) != 12) return AVERROR_EIO;
    if (memcmp(h,"RIFF",4) || memcmp(h+8,"WAVE",4)) return AVERROR_EINVAL;
    memset(mi,0,sizeof(*mi));
    mi->total_samples = -1;
    while (!found_data) {
        if (fread(ch,1,8,f) != 8) return AVERROR_EIO;
