            uint32_t sz = rd32(ch+4);
            if (!memcmp(ch,"fmt ",4)) {
                uint8_t b[40];
                int rd = sz < 40 ? (int)sz : 40;
                if (fread(b,1,rd,f) != (size_t)rd) return AVERROR_EIO;
                if (sz > 40 && fseek(f, sz-40, SEEK_CUR)) return AVERROR_EIO;
                fmt = rd16(b); channels = rd16(b+2); rate = (int)rd32(b+4);
                bits = rd16(b+14);
                if (fmt == 0xFFFE && sz >= 40) { bits = rd16(b+14); }
                mi->bits = bits;
                mi->channels = channels;
                mi->sample_rate = rate;
            } else if (!memcmp(ch,"data",4)) {
                data_off = ftello(f);
                data_len = sz;
                found_data = 1;
                if (sz == 0xFFFFFFFFu) { fseeko(f, 0, SEEK_END); data_len = ftello(f) - data_off; }
            } else {
                if (sz & 1) sz++;
                if (sz && fseek(f, sz, SEEK_CUR)) return AVERROR_EIO;
            }
        }
    }
    mi->data_off = data_off;
    mi->data_len = data_len;
    mi->total_samples = (channels && bits) ? data_len / ((bits/8) * channels) : 0;
    mi->duration_us = (mi->total_samples > 0 && rate)
        ? (int64_t)((double)mi->total_samples * 1000000.0 / rate) : 0;
    return 0;
}

/* read interleaved samples; returns count of frames read */
int wav_read_frames(FILE *f, MediaInfo *mi, int32_t *buf, int max_frames)
{
    int ch = mi->channels, bits = mi->bits;
    int bytes = bits/8;
    int64_t remaining = mi->data_len / (bytes*ch);
    int n = max_frames;
    uint8_t *raw;
    int i, c;
    if (n > remaining) n = (int)remaining;
    if (n <= 0) return 0;
    raw = (uint8_t*)malloc((size_t)n*bytes*ch);
    if (!raw) return AVERROR_NOMEM;
    if (fread(raw,1,(size_t)n*bytes*ch,f) != (size_t)n*bytes*ch) { free(raw); return AVERROR_EIO; }
    mi->data_len -= (int64_t)n*bytes*ch;
    for (i = 0; i < n; i++)
        for (c = 0; c < ch; c++) {
            const uint8_t *p = raw + ((size_t)i*ch + c)*bytes;
            int64_t v = 0;
            switch (bits) {
            case 8: v = (int8_t)p[0]; break;
            case 16: v = (int16_t)(p[0] | (p[1]<<8)); break;
            case 24: v = (int32_t)((p[0] | (p[1]<<8) | (p[2]<<16)) << 8) >> 8; break;
            case 32: default: v = (int32_t)rd32(p); break;
