    fwrite("RIFF",1,4,f);
    wr32(b, (uint32_t)(36 + data_bytes + 0)); fwrite(b,1,4,f);
    fwrite("WAVE",1,4,f);
    fwrite("fmt ",1,4,f);
    wr32(b, 16); fwrite(b,1,4,f);
    wr16(b, (uint16_t)fmt); fwrite(b,1,2,f);
    wr16(b, (uint16_t)ch); fwrite(b,1,2,f);
    wr32(b, (uint32_t)(sr * ch * bits/8)); fwrite(b,1,4,f);
    wr16(b, (uint16_t)(ch*bits/8)); fwrite(b,1,2,f);
    wr16(b, (uint16_t)bits); fwrite(b,1,2,f);
    /* LIST/INFO with ISFT */
    {
        const char *tag = FFM_LAVF;
        int tl = (int)strlen(tag) + 1;
        int pad = tl & 1;
        int listlen = 4 + 4 + 4 + tl + pad;
        fwrite("LIST",1,4,f);
