                else { b[0]=(uint8_t)v; b[1]=(uint8_t)(v>>8); b[2]=(uint8_t)(v>>16); }
                fwrite(b,1,3,f); break;
            case 32:
                if (be) { b[0]=(uint8_t)(v>>24); b[1]=(uint8_t)(v>>16); b[2]=(uint8_t)(v>>8); b[3]=(uint8_t)v; }
                else { b[0]=(uint8_t)v; b[1]=(uint8_t)(v>>8); b[2]=(uint8_t)(v>>16); b[3]=(uint8_t)(v>>24); }
                fwrite(b,1,4,f); break;
            }
        }
    return 0;
}

int pcm_raw_write(FILE *f, int bits, int ch, const int32_t *data, int nsamples, int be, int isfloat)
{
    (void)isfloat;
    return pcm_write_frames(f, bits, ch, data, nsamples, be);
}
