            case 24: v = (int32_t)((p[0] | (p[1]<<8) | (p[2]<<16)) << 8) >> 8; break;
            case 32: default: v = (int32_t)rd32(p); break;
            }
            buf[(size_t)i*ch + c] = (int32_t)v;
        }
    free(raw);
    return n;
}

static void wr16(uint8_t *p, uint16_t v){ p[0]=(uint8_t)v; p[1]=(uint8_t)(v>>8); }
static void wr32(uint8_t *p, uint32_t v){ p[0]=(uint8_t)v; p[1]=(uint8_t)(v>>8); p[2]=(uint8_t)(v>>16); p[3]=(uint8_t)(v>>24); }

int wav_write_header(FILE *f, int sr, int ch, int bits, int64_t data_bytes)
{
    uint8_t b[64];
    int fmt = 1;
    if (bits == 32) fmt = 1;
    fwrite("RIFF",1,4,f);
    wr32(b, (uint32_t)(36 + data_bytes + 0)); fwrite(b,1,4,f);
    fwrite("WAVE",1,4,f);
    fwrite("fmt ",1,4,f);
    wr32(b, 16); fwrite(b,1,4,f);
    wr16(b, (uint16_t)fmt); fwrite(b,1,2,f);
    wr16(b, (uint16_t)ch); fwrite(b,1,2,f);
    wr32(b, (uint32_t)(sr * ch * bits/8)); fwrite(b,1,4,f);
    wr16(b, (uint16_t)(ch*bits/8)); fwrite(b,1,2,f);
    wr16(b, (uint16_t)bits); fwrite(b,1,2,f);
    /* LIST/INFO with ISFT */
    {
        const char *tag = FFM_LAVF;
        int tl = (int)strlen(tag) + 1;
        int pad = tl & 1;
        int listlen = 4 + 4 + 4 + tl + pad;
        fwrite("LIST",1,4,f);
        wr32(b, (uint32_t)listlen); fwrite(b,1,4,f);
        fwrite("INFO",1,4,f);
        fwrite("ISFT",1,4,f);
        wr32(b, (uint32_t)tl); fwrite(b,1,4,f);
        fwrite(tag,1,tl,f);
        if (pad) fputc(0,f);
    }
    fwrite("data",1,4,f);
    wr32(b, (uint32_t)data_bytes); fwrite(b,1,4,f);
    return 0;
}

void wav_fix_sizes(FILE *f, int64_t data_bytes)
{
    uint8_t b[4];
    fseeko(f, 4, SEEK_SET);
    wr32(b, (uint32_t)(36 + data_bytes)); fwrite(b,1,4,f);
    fseeko(f, 0, SEEK_END);
    fseeko(f, 0 - (data_bytes + 4), SEEK_CUR);
    wr32(b, (uint32_t)data_bytes); fwrite(b,1,4,f);
    fseeko(f, 0, SEEK_END);
}

int pcm_write_frames(FILE *f, int bits, int ch, const int32_t *data, int nsamples, int be)
{
    int i, c;
    for (i = 0; i < nsamples; i++)
        for (c = 0; c < ch; c++) {
            int32_t v = data[(size_t)i*ch + c];
            uint8_t b[8];
            switch (bits) {
            case 8: fputc((uint8_t)(v & 0xff), f); break;
            case 16:
                if (be) { b[0] = (uint8_t)(v >> 8); b[1] = (uint8_t)v; }
                else { b[0] = (uint8_t)v; b[1] = (uint8_t)(v >> 8); }
                fwrite(b,1,2,f); break;
            case 24:
                if (be) { b[0]=(uint8_t)(v>>16); b[1]=(uint8_t)(v>>8); b[2]=(uint8_t)v; }
                else { b[0]=(uint8_t)v; b[1]=(uint8_t)(v>>8); b[2]=(uint8_t)(v>>16); }
                fwrite(b,1,3,f); break;
            case 32:
                if (be) { b[0]=(uint8_t)(v>>24); b[1]=(uint8_t)(v>>16); b[2]=(uint8_t)(v>>8); b[3]=(uint8_t)v; }
                else { b[0]=(uint8_t)v; b[1]=(uint8_t)(v>>8); b[2]=(uint8_t)(v>>16); b[3]=(uint8_t)(v>>24); }
                fwrite(b,1,4,f); break;
            }
        }
    return 0;
}

int pcm_raw_write(FILE *f, int bits, int ch, const int32_t *data, int nsamples, int be, int isfloat)
{
    (void)isfloat;
    return pcm_write_frames(f, bits, ch, data, nsamples, be);
}
