#include "ffm.h"
#include "lists_blob.h"

static int lzd(const unsigned char *in, int inlen, unsigned char *out, int outcap)
{
    int i = 0, o = 0;
    while (i < inlen) {
        int f = in[i++];
        if (f == 0) {
            int ln = in[i++];
            if (o + ln > outcap) return -1;
            memcpy(out + o, in + i, ln); i += ln; o += ln;
        } else {
            int off = in[i] | (in[i+1] << 8);
            int ln = in[i+2];
            int p;
            i += 3;
            if (o + ln > outcap) return -1;
            p = o - off;
            for (; ln > 0; ln--) out[o++] = out[p++];
        }
    }
    return o;
}

int ff_lists_decompress(const char *name, unsigned char **out, int *outlen)
{
    const ListEntry *e;
    for (e = lists_table; e->name; e++) {
        if (!strcmp(e->name, name)) {
            unsigned char *buf = (unsigned char*)malloc(e->origlen + 1);
            int n;
            if (!buf) return AVERROR_NOMEM;
            n = lzd(lists_blob + e->off, e->len, buf, e->origlen);
            if (n < 0) { free(buf); return AVERROR_EINVAL; }
            buf[n] = 0;
            *out = buf; *outlen = n;
            return 0;
        }
    }
    return AVERROR_ENOENT;
}
