}

static int transcode(void)
{
    FILE *fi = NULL, *fo = NULL;
    MediaInfo mi;
    unsigned char *vc = NULL;
    const Muxer *mux = NULL;
    uint8_t *probe = NULL;
    int flac_in = 0, wav_in = 0;
    int ret = 0;
    int64_t audio_bytes = 0, other_bytes = 0;
