    }
    /* print input info */
    {
        int64_t sz = 0;
        fseeko(fi, 0, SEEK_END); sz = ftello(fi); fseeko(fi, mi.data_off, SEEK_SET);
        ff_log(AV_LOG_INFO, "Input #0, %s, from '%s':\n", flac_in ? "flac" : "wav", infilename);
        if (flac_in && vc) {
            ff_log(AV_LOG_INFO, "  Metadata:\n");
            ff_log(AV_LOG_INFO, "    encoder         : %s\n", FFM_LAVF);
        } else if (!flac_in) {
            /* wav: check for LIST/INFO/ISFT */
            ff_log(AV_LOG_INFO, "  Metadata:\n");
            ff_log(AV_LOG_INFO, "    encoder         : %s\n", FFM_LAVF);
        }
        fmt_time(tbuf, mi.duration_us);
        ff_log(AV_LOG_INFO, "  Duration: %s, bitrate: %d kb/s\n", tbuf,
               (int)((sz * 8.0) / (mi.duration_us ? (double)mi.duration_us/1000000.0 : 1) / 1000.0));
        if (flac_in)
            ff_log(AV_LOG_INFO, "  Stream #0:0: Audio: flac, %d Hz, %s, s%d\n", mi.sample_rate,
                   chan_layout_name(mi.channels) ? chan_layout_name(mi.channels) : "unknown",
                   mi.bits);
        else {
            int br = (int)((double)mi.sample_rate * mi.bits * mi.channels / 1000.0);
            ff_log(AV_LOG_INFO, "  Stream #0:0: Audio: pcm_s16le ([1][0][0][0] / 0x0001), %d Hz, %s, s%d, %d kb/s\n",
                   mi.sample_rate, chan_layout_name(mi.channels) ? chan_layout_name(mi.channels) : "unknown",
                   mi.bits, br);
        }
    }
    if (!outfilename) {
        ff_log(AV_LOG_ERROR, "At least one output file must be specified\n");
        ret = 1; goto end;
    }
    /* pick muxer */
    if (force_fmt) { mux = find_muxer_by_name(force_fmt);
        if (!mux) {
            ff_log(AV_LOG_ERROR, "[AVFormatContext @ 0x000000000000] Requested output format '%s' is not known.\n", force_fmt);
            ff_log(AV_LOG_ERROR, "[out#0 @ 0x000000000000] Error initializing the muxer for %s: Invalid argument\n", outfilename);
            ff_log(AV_LOG_ERROR, "Error opening output file %s.\n", outfilename);
            ff_log(AV_LOG_ERROR, "Error opening output files: Invalid argument\n");
            ret = 234; goto end;
        }
    } else mux = find_muxer_by_ext(outfilename);
    if (!mux) {
        ff_log(AV_LOG_ERROR, "[AVFormatContext @ 0x000000000000] Unable to choose an output format for '%s'; use a standard extension for the filename or specify the format manually.\n", outfilename);
        ff_log(AV_LOG_ERROR, "[out#0 @ 0x000000000000] Error initializing the muxer for %s: Invalid argument\n", outfilename);
        ff_log(AV_LOG_ERROR, "Error opening output file %s.\n", outfilename);
        ff_log(AV_LOG_ERROR, "Error opening output files: Invalid argument\n");
        ret = 234; goto end;
    }
    /* overwrite check */
    {
        FILE *t = fopen(outfilename, "rb");
        if (t) {
            fclose(t);
            if (never_overwrite || !overwrite) {
                if (ff_log_level >= AV_LOG_INFO) {
                    fprintf(stderr, "File '%s' already exists. Overwrite? [y/N] ", outfilename);
                    if (never_overwrite || !overwrite) {
                        ff_log(AV_LOG_ERROR, "Not overwriting - exiting\n");
                        ff_log(AV_LOG_ERROR, "Error opening output file %s.\n", outfilename);
                        free(t); /* noop */
                        ret = AVERROR_EINVAL; goto end;
                    }
                }
            }
        }
    }
