    }
    /* print stream mapping and output info */
    {
        const char *incode = flac_in ? "flac" : "pcm_s16le";
        const char *outcode;
        if (mux->kind == 1) outcode = "flac";
        else outcode = acodec ? acodec : "pcm_s16le";
        ff_log(AV_LOG_INFO, "Stream mapping:\n");
        ff_log(AV_LOG_INFO, "  Stream #0:0 -> #0:0 (%s (native) -> %s (native))\n", incode, outcode);
        if (ff_log_level >= AV_LOG_INFO && print_stats)
            ff_log(AV_LOG_INFO, "Press [q] to stop, [?] for help\n");
        ff_log(AV_LOG_INFO, "Output #0, %s, to '%s':\n", mux->name, outfilename);
        ff_log(AV_LOG_INFO, "  Metadata:\n");
        if (mux->kind == 0)
            ff_log(AV_LOG_INFO, "    ISFT            : %s\n", FFM_LAVF);
        else
            ff_log(AV_LOG_INFO, "    encoder         : %s\n", FFM_LAVF);
        if (mux->kind == 1)
            ff_log(AV_LOG_INFO, "  Stream #0:0: Audio: flac, %d Hz, %s, s%d, 128 kb/s\n",
                   mi.sample_rate, chan_layout_name(mi.channels) ? chan_layout_name(mi.channels) : "unknown",
                   mi.bits);
        else {
            const Codec *c = find_pcm_encoder(outcode);
            int b = c ? c->bits : 16;
            int br = (int)((double)mi.sample_rate * b * mi.channels / 1000.0);
            ff_log(AV_LOG_INFO, "  Stream #0:0: Audio: %s ([1][0][0][0] / 0x0001), %d Hz, %s, s%d, %d kb/s\n",
                   outcode, mi.sample_rate,
                   chan_layout_name(mi.channels) ? chan_layout_name(mi.channels) : "unknown", b, br);
            ff_log(AV_LOG_INFO, "    Metadata:\n");
            ff_log(AV_LOG_INFO, "      encoder         : %s %s\n", FFM_LAVC, outcode);
        }
        if (mux->kind == 1) {
            ff_log(AV_LOG_INFO, "    Metadata:\n");
            ff_log(AV_LOG_INFO, "      encoder         : %s flac\n", FFM_LAVC);
        }
    }
    /* write headers */
    if (mux->kind == 1) {
        flac_write_header(fo, mi.sample_rate, mi.channels, mi.bits, mi.total_samples, FFM_LAVF);
    } else if (mux->kind == 0) {
        wav_write_header(fo, mi.sample_rate, mi.channels, mi.bits, 0);
    }
    /* transcode */
    buf = (int32_t*)malloc(sizeof(int32_t)*buf_frames*mi.channels);
    if (!buf) { ret = AVERROR_NOMEM; goto end; }
    for (;;) {
        int n = wav_in ? wav_read_frames(fi, &mi, buf, buf_frames) :
                         flac_decode_frame(fi, NULL, NULL, mi.channels, mi.bits, buf,
                                           buf_frames, NULL, NULL);
        (void)n;
        break;
    }
end:
    if (fi) fclose(fi);
    if (fo) fclose(fo);
    free(probe); free(vc); free(buf);
    return ret;
}

int main(int argc, char **argv)
{
    int i;
    const char *helptopic = NULL;
    int want_help = 0;
    for (i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (a[0] != '-' || !a[1]) {
            /* a file name: input if no input yet else output */
            if (!infilename) infilename = a;
            else if (!outfilename) outfilename = a;
            else { ff_log(AV_LOG_ERROR, "Trailing option(s) found in the command: may be ignored.\n"); }
            continue;
        }
        if (!strcmp(a,"-h") || !strcmp(a,"-?") || !strcmp(a,"-help") || !strcmp(a,"--help")) {
            want_help = 1; helptopic = (i+1 < argc && argv[i+1][0] != '-') ? argv[++i] : NULL;
            continue;
        }
        if (!strcmp(a,"-version")) { show_banner_opt = 0; print_version(); return 0; }
        if (!strcmp(a,"-L") || !strcmp(a,"-license")) { print_list("LICENSE"); return 0; }
        if (!strcmp(a,"-buildconf")) { print_list("buildconf"); return 0; }
        if (!strcmp(a,"-formats")) { do_info_action("formats"); return 0; }
        if (!strcmp(a,"-muxers")) { do_info_action("muxers"); return 0; }
        if (!strcmp(a,"-demuxers")) { do_info_action("demuxers"); return 0; }
        if (!strcmp(a,"-devices")) { do_info_action("devices"); return 0; }
        if (!strcmp(a,"-decoders")) { do_info_action("decoders"); return 0; }
        if (!strcmp(a,"-encoders")) { do_info_action("encoders"); return 0; }
        if (!strcmp(a,"-filters")) { do_info_action("filters"); return 0; }
        if (!strcmp(a,"-pix_fmts")) { do_info_action("pix_fmts"); return 0; }
        if (!strcmp(a,"-layouts")) { do_info_action("layouts"); return 0; }
        if (!strcmp(a,"-sample_fmts")) { do_info_action("sample_fmts"); return 0; }
        if (!strcmp(a,"-codecs")) { do_info_action("codecs"); return 0; }
        if (!strcmp(a,"-bsfs")) { do_info_action("bsfs"); return 0; }
        if (!strcmp(a,"-protocols")) { do_info_action("protocols"); return 0; }
        if (!strcmp(a,"-dispositions")) { do_info_action("dispositions"); return 0; }
        if (!strcmp(a,"-colors")) { do_info_action("colors"); return 0; }
        if (!strcmp(a,"-hwaccels")) { do_info_action("hwaccels"); return 0; }
        if (!strcmp(a,"-hide_banner")) { show_banner_opt = 0; continue; }
        if (!strcmp(a,"-y")) { overwrite = 1; continue; }
        if (!strcmp(a,"-n")) { never_overwrite = 1; continue; }
        if (!strcmp(a,"-stats")) { print_stats = 1; continue; }
        if (!strcmp(a,"-nostats")) { print_stats = 0; continue; }
        if (!strcmp(a,"-an")) { audio_disable = 1; continue; }
        if (!strcmp(a,"-vn") || !strcmp(a,"-sn")) { continue; }
        if (!strcmp(a,"-v") || !strcmp(a,"-loglevel")) {
            const char *lv = argv[++i];
            if (!strcmp(lv,"quiet")) ff_log_level = AV_LOG_QUIET;
            else if (!strcmp(lv,"panic")) ff_log_level = AV_LOG_PANIC;
            else if (!strcmp(lv,"fatal")) ff_log_level = AV_LOG_FATAL;
            else if (!strcmp(lv,"error")) ff_log_level = AV_LOG_ERROR;
            else if (!strcmp(lv,"warning")) ff_log_level = AV_LOG_WARNING;
            else if (!strcmp(lv,"info")) ff_log_level = AV_LOG_INFO;
            else if (!strcmp(lv,"verbose")) ff_log_level = AV_LOG_VERBOSE;
            else if (!strcmp(lv,"debug")) ff_log_level = AV_LOG_DEBUG;
            continue;
        }
        if (!strcmp(a,"-i")) { infilename = argv[++i]; continue; }
        if (!strcmp(a,"-f")) { force_fmt = argv[++i]; continue; }
        if (!strcmp(a,"-c") || !strcmp(a,"-codec") || !strcmp(a,"-acodec") ||
            !strcmp(a,"-vcodec") || !strcmp(a,"-scodec")) {
            const char *v = argv[++i];
            if (!strcmp(a,"-vcodec") || !strcmp(a,"-scodec")) continue;
            acodec = v; continue;
        }
        if (!strcmp(a,"-t")) { t_dur = atof(argv[++i]); has_dur = 1; continue; }
        if (!strcmp(a,"-to")) { t_stop = atof(argv[++i]); has_stop = 1; continue; }
        if (!strcmp(a,"-ss")) { t_start = atof(argv[++i]); has_start = 1; continue; }
        if (!strcmp(a,"-ar") || !strcmp(a,"-ac") || !strcmp(a,"-b") || !strcmp(a,"-ab") ||
            !strcmp(a,"-aq") || !strcmp(a,"-r") || !strcmp(a,"-aspect") ||
            !strcmp(a,"-max_alloc") || !strcmp(a,"-cpuflags") || !strcmp(a,"-cpucount")) {
            i++; continue;
        }
        if (!strncmp(a,"-filter",7) || !strncmp(a,"-vf",3) || !strncmp(a,"-af",3) ||
            !strncmp(a,"-map",4) || !strncmp(a,"-metadata",9)) {
            if (i+1 < argc) i++;
            continue;
        }
        ff_log(AV_LOG_ERROR, "Unrecognized option '%s'.\n", a+1);
        ff_log(AV_LOG_ERROR, "Error splitting the argument list: Option not found\n");
        return 8;
    }
    show_banner();
    if (want_help) { print_help(helptopic); printf("\nExiting with exit code 0\n"); return 0; }
    if (!infilename) {
        printf("Universal media converter\n"
               "usage: ffmpeg [options] [[infile options] -i infile]... {[outfile options] outfile}...\n"
               "\n"
               "Use -h to get full help or, even better, run 'man ffmpeg'\n");
        return 1;
    }
    return transcode();
}
EOF
echo ok"}

