/* --------------------------------------------------------------- helpers */
static void fmt_time(char *buf, int64_t us)
{
    int64_t t = us;
    int h, m, s, cs;
    if (t < 0) t = 0;
    cs = (int)((t / 10000) % 100);
    s = (int)(t / 1000000) % 60;
    m = (int)(t / 60000000) % 60;
    h = (int)(t / 3600000000LL);
    sprintf(buf, "%02d:%02d:%02d.%02d", h, m, s, cs);
}

static const char *chan_layout_name(int ch)
{
