/* --------------------------------------------------------- info printing */
static void print_list(const char *name)
{
    unsigned char *txt = NULL; int len = 0;
    if (ff_lists_decompress(name, &txt, &len) == 0) {
        fwrite(txt, 1, len, stdout);
        free(txt);
