}

static void print_help(const char *topic)
{
    if (!topic || !*topic || !strcmp(topic,"long")) {
        char buf[32];
        sprintf(buf, "%s", !topic ? "h_basic" : "h_long");
        print_list(!topic ? "h" : "h_long");
    } else if (!strcmp(topic,"full")) {
        print_list("h_full");
    } else {
        ff_log(AV_LOG_INFO, "Unknown help option '%s'.\n", topic);
        print_list("h");
    }
}

