/* ------------------------------------------------------------- muxer find */
typedef struct { const char *name; const char *ext; int kind; } Muxer;
/* kind: 0 = wav, 1 = flac, 2 = raw pcm le, 3 = raw pcm be */
static const Muxer muxers[] = {
    {"wav","wav",0},{"flac","flac",1},
    {"u8","u8",2},{"s8","s8",2},{"u16le","u16le",2},{"s16le","s16le",2},
    {"u16be","u16be",3},{"s16be","s16be",3},{"u24le","u24le",2},{"s24le","s24le",2},
    {"u24be","u24be",3},{"s24be","s24be",3},{"u32le","u32le",2},{"s32le","s32le",2},
    {"u32be","u32be",3},{"s32be","s32be",3},{"f32le","f32le",2},{"f32be","f32be",3},
    {"f64le","f64le",2},{"f64be","f64be",3},
    {"alaw","alaw",2},{"mulaw","mulaw",2},
    {0,0,0}
};

static const Muxer *find_muxer_by_ext(const char *fn)
{
    const char *dot = strrchr(fn, '.');
    const Muxer *m;
    if (!dot) return NULL;
    dot++;
    for (m = muxers; m->name; m++)
        if (m->ext && !strcmp(dot, m->ext)) return m;
    return NULL;
}

static const Muxer *find_muxer_by_name(const char *name)
{
    const Muxer *m;
    for (m = muxers; m->name; m++)
        if (!strcmp(name, m->name)) return m;
    return NULL;
}

/* ------------------------------------------------------------- codec find */
typedef struct { const char *name; int bits; } Codec;
static const Codec pcm_encoders[] = {
    {"pcm_s16le",16},{"pcm_s16be",16},{"pcm_u8",8},{"pcm_s8",8},
    {"pcm_s24le",24},{"pcm_s24be",24},{"pcm_u16le",16},{"pcm_u16be",16},
    {"pcm_u24le",24},{"pcm_u24be",24},{"pcm_s32le",32},{"pcm_s32be",32},
    {"pcm_u32le",32},{"pcm_u32be",32},{"pcm_f32le",32},{"pcm_f32be",32},
    {"pcm_f64le",64},{"pcm_f64be",64},
    {0,0}
};

static const Codec *find_pcm_encoder(const char *n)
{
    const Codec *c;
    for (c = pcm_encoders; c->name; c++) if (!strcmp(n,c->name)) return c;
    return NULL;
}

/* ----------------------------------------------------------------- main  */
static int do_info_action(const char *listname)
{
    print_list(listname);
    return 0;
}

static int64_t parse_time_us(const char *s)
{
    double d = atof(s);
    return (int64_t)(d * 1000000.0);
}

static int transcode(void)
{
    FILE *fi = NULL, *fo = NULL;
    MediaInfo mi;
    unsigned char *vc = NULL;
    const Muxer *mux = NULL;
    uint8_t *probe = NULL;
    int flac_in = 0, wav_in = 0;
    int ret = 0;
    int64_t audio_bytes = 0, other_bytes = 0;
    int out_bits = 16;
    int max_lpc_order = 8, min_part = 0, max_part = 6;
    int32_t *buf = NULL;
    int buf_frames = 4608;
    int64_t total_written = 0;
    char tbuf[32];

    fi = fopen(infilename, "rb");
    if (!fi) {
        char pre[64];
        ff_set_log_prefix(NULL);
        ff_log(AV_LOG_ERROR, "[in#0 @ 0x000000000000] Error opening input: %s\n", strerror(ENOENT));
        ff_log(AV_LOG_ERROR, "Error opening input file %s.\n", infilename);
        ff_log(AV_LOG_ERROR, "Error opening input files: %s\n", strerror(ENOENT));
        return 254;
    }
    probe = (uint8_t*)malloc(64);
    memset(probe, 0, 64);
    { size_t n = fread(probe, 1, 64, fi); (void)n; fseek(fi, 0, SEEK_SET); }
    if (flac_probe(probe, 64)) flac_in = 1;
    else if (wav_probe(probe, 64)) wav_in = 1;
    else { ff_log(AV_LOG_ERROR, "Unknown format\n"); ret = AVERROR_EINVAL; goto end; }
    memset(&mi, 0, sizeof(mi));
    if (flac_in) {
        ret = flac_read_header(fi, &mi, &vc);
        if (ret < 0) goto end;
        /* metadata from vorbis comment: only "encoder" is shown */
    } else {
        ret = wav_read_header(fi, &mi);
        if (ret < 0) goto end;
        ff_log(AV_LOG_INFO, "[aist#0:0/pcm_s16le @ 0x000000000000] Guessed Channel Layout: %s\n",
               chan_layout_name(mi.channels) ? chan_layout_name(mi.channels) : "unknown");
    }
    /* print input info */
    {
        int64_t sz = 0;
        fseeko(fi, 0, SEEK_END); sz = ftello(fi); fseeko(fi, mi.data_off, SEEK_SET);
        ff_log(AV_LOG_INFO, "Input #0, %s, from '%s':\n", flac_in ? "flac" : "wav", infilename);
        if (flac_in && vc) {
            ff_log(AV_LOG_INFO, "  Metadata:\n");
            ff_log(AV_LOG_INFO, "    encoder         : %s\n", FFM_LAVF);
        } else if (!flac_in) {
            /* wav: check for LIST/INFO/ISFT */
            ff_log(AV_LOG_INFO, "  Metadata:\n");
            ff_log(AV_LOG_INFO, "    encoder         : %s\n", FFM_LAVF);
        }
        fmt_time(tbuf, mi.duration_us);
        ff_log(AV_LOG_INFO, "  Duration: %s, bitrate: %d kb/s\n", tbuf,
               (int)((sz * 8.0) / (mi.duration_us ? (double)mi.duration_us/1000000.0 : 1) / 1000.0));
        if (flac_in)
            ff_log(AV_LOG_INFO, "  Stream #0:0: Audio: flac, %d Hz, %s, s%d\n", mi.sample_rate,
                   chan_layout_name(mi.channels) ? chan_layout_name(mi.channels) : "unknown",
                   mi.bits);
        else {
            int br = (int)((double)mi.sample_rate * mi.bits * mi.channels / 1000.0);
            ff_log(AV_LOG_INFO, "  Stream #0:0: Audio: pcm_s16le ([1][0][0][0] / 0x0001), %d Hz, %s, s%d, %d kb/s\n",
                   mi.sample_rate, chan_layout_name(mi.channels) ? chan_layout_name(mi.channels) : "unknown",
                   mi.bits, br);
        }
    }
    if (!outfilename) {
        ff_log(AV_LOG_ERROR, "At least one output file must be specified\n");
        ret = 1; goto end;
    }
    /* pick muxer */
    if (force_fmt) { mux = find_muxer_by_name(force_fmt);
        if (!mux) {
            ff_log(AV_LOG_ERROR, "[AVFormatContext @ 0x000000000000] Requested output format '%s' is not known.\n", force_fmt);
            ff_log(AV_LOG_ERROR, "[out#0 @ 0x000000000000] Error initializing the muxer for %s: Invalid argument\n", outfilename);
            ff_log(AV_LOG_ERROR, "Error opening output file %s.\n", outfilename);
            ff_log(AV_LOG_ERROR, "Error opening output files: Invalid argument\n");
            ret = 234; goto end;
        }
    } else mux = find_muxer_by_ext(outfilename);
    if (!mux) {
        ff_log(AV_LOG_ERROR, "[AVFormatContext @ 0x000000000000] Unable to choose an output format for '%s'; use a standard extension for the filename or specify the format manually.\n", outfilename);
        ff_log(AV_LOG_ERROR, "[out#0 @ 0x000000000000] Error initializing the muxer for %s: Invalid argument\n", outfilename);
        ff_log(AV_LOG_ERROR, "Error opening output file %s.\n", outfilename);
        ff_log(AV_LOG_ERROR, "Error opening output files: Invalid argument\n");
        ret = 234; goto end;
    }
    /* overwrite check */
    {
        FILE *t = fopen(outfilename, "rb");
        if (t) {
            fclose(t);
            if (never_overwrite || !overwrite) {
                if (ff_log_level >= AV_LOG_INFO) {
                    fprintf(stderr, "File '%s' already exists. Overwrite? [y/N] ", outfilename);
                    if (never_overwrite || !overwrite) {
                        ff_log(AV_LOG_ERROR, "Not overwriting - exiting\n");
                        ff_log(AV_LOG_ERROR, "Error opening output file %s.\n", outfilename);
                        free(t); /* noop */
                        ret = AVERROR_EINVAL; goto end;
                    }
                }
            }
        }
    }
    /* select encoder */
    out_bits = 16;
    if (acodec && strcmp(acodec,"copy") && !find_pcm_encoder(acodec) && strcmp(acodec,"flac")) {
        ff_log(AV_LOG_ERROR, "[aost#0:0 @ 0x000000000000] Unknown encoder '%s'\n", acodec);
        ff_log(AV_LOG_ERROR, "[aost#0:0 @ 0x000000000000] Error selecting an encoder\n");
        ff_log(AV_LOG_ERROR, "Error opening output file %s.\n", outfilename);
        ff_log(AV_LOG_ERROR, "Error opening output files: Encoder not found\n");
        ret = 8; goto end;
    }
    if (acodec && !strcmp(acodec,"flac")) { /* flac output */
        /* nothing */
    } else if (acodec) {
        const Codec *c = find_pcm_encoder(acodec);
        if (c) out_bits = c->bits;
    }
    fo = fopen(outfilename, "wb");
    if (!fo) {
        ff_log(AV_LOG_ERROR, "[out#0/%s @ 0x000000000000] Error opening output %s: %s\n",
               mux->name, outfilename, strerror(ENOENT));
        ff_log(AV_LOG_ERROR, "Error opening output file %s.\n", outfilename);
        ff_log(AV_LOG_ERROR, "Error opening output files: %s\n", strerror(ENOENT));
        ret = 254; goto end;
    }
    /* print stream mapping and output info */
    {
        const char *incode = flac_in ? "flac" : "pcm_s16le";
        const char *outcode;
        if (mux->kind == 1) outcode = "flac";
        else outcode = acodec ? acodec : "pcm_s16le";
        ff_log(AV_LOG_INFO, "Stream mapping:\n");
        ff_log(AV_LOG_INFO, "  Stream #0:0 -> #0:0 (%s (native) -> %s (native))\n", incode, outcode);
        if (ff_log_level >= AV_LOG_INFO && print_stats)
            ff_log(AV_LOG_INFO, "Press [q] to stop, [?] for help\n");
        ff_log(AV_LOG_INFO, "Output #0, %s, to '%s':\n", mux->name, outfilename);
        ff_log(AV_LOG_INFO, "  Metadata:\n");
        if (mux->kind == 0)
            ff_log(AV_LOG_INFO, "    ISFT            : %s\n", FFM_LAVF);
        else
            ff_log(AV_LOG_INFO, "    encoder         : %s\n", FFM_LAVF);
        if (mux->kind == 1)
            ff_log(AV_LOG_INFO, "  Stream #0:0: Audio: flac, %d Hz, %s, s%d, 128 kb/s\n",
                   mi.sample_rate, chan_layout_name(mi.channels) ? chan_layout_name(mi.channels) : "unknown",
                   mi.bits);
        else {
            const Codec *c = find_pcm_encoder(outcode);
            int b = c ? c->bits : 16;
            int br = (int)((double)mi.sample_rate * b * mi.channels / 1000.0);
            ff_log(AV_LOG_INFO, "  Stream #0:0: Audio: %s ([1][0][0][0] / 0x0001), %d Hz, %s, s%d, %d kb/s\n",
                   outcode, mi.sample_rate,
                   chan_layout_name(mi.channels) ? chan_layout_name(mi.channels) : "unknown", b, br);
            ff_log(AV_LOG_INFO, "    Metadata:\n");
            ff_log(AV_LOG_INFO, "      encoder         : %s %s\n", FFM_LAVC, outcode);
        }
        if (mux->kind == 1) {
