static const Muxer muxers[] = {
    {"wav","wav",0},{"flac","flac",1},
    {"u8","u8",2},{"s8","s8",2},{"u16le","u16le",2},{"s16le","s16le",2},
    {"u16be","u16be",3},{"s16be","s16be",3},{"u24le","u24le",2},{"s24le","s24le",2},
    {"u24be","u24be",3},{"s24be","s24be",3},{"u32le","u32le",2},{"s32le","s32le",2},
    {"u32be","u32be",3},{"s32be","s32be",3},{"f32le","f32le",2},{"f32be","f32be",3},
    {"f64le","f64le",2},{"f64be","f64be",3},
    {"alaw","alaw",2},{"mulaw","mulaw",2},
    {0,0,0}
};

static const Muxer *find_muxer_by_ext(const char *fn)
{
    const char *dot = strrchr(fn, '.');
    const Muxer *m;
    if (!dot) return NULL;
    dot++;
    for (m = muxers; m->name; m++)
        if (m->ext && !strcmp(dot, m->ext)) return m;
    return NULL;
}

static const Muxer *find_muxer_by_name(const char *name)
{
    const Muxer *m;
    for (m = muxers; m->name; m++)
        if (!strcmp(name, m->name)) return m;
    return NULL;
}

/* ------------------------------------------------------------- codec find */
typedef struct { const char *name; int bits; } Codec;
static const Codec pcm_encoders[] = {
    {"pcm_s16le",16},{"pcm_s16be",16},{"pcm_u8",8},{"pcm_s8",8},
    {"pcm_s24le",24},{"pcm_s24be",24},{"pcm_u16le",16},{"pcm_u16be",16},
    {"pcm_u24le",24},{"pcm_u24be",24},{"pcm_s32le",32},{"pcm_s32be",32},
    {"pcm_u32le",32},{"pcm_u32be",32},{"pcm_f32le",32},{"pcm_f32be",32},
    {"pcm_f64le",64},{"pcm_f64be",64},
    {0,0}
};

static const Codec *find_pcm_encoder(const char *n)
{
    const Codec *c;
    for (c = pcm_encoders; c->name; c++) if (!strcmp(n,c->name)) return c;
