/* FLAC encoder (reverse engineered) */
#include "codec.h"

static void apply_welch_sq(const int32_t *s, int n, double *x)
{
    int i;
    for (i = 0; i < n; i++) {
        double t = fabs(2.0*i - n + 1.0) / (double)(n + 1);
        double w = (1.0 - t) * (1.0 - t);
        x[i] = (double)s[i] * w;
    }
}
static void compute_autocorr(const double *x, int len, int lag, double *autoc)
{
    int i, j;
    for (j = 0; j <= lag; j++) {
        double sum = 0.0;
        for (i = j; i < len; i++) sum += x[i] * x[i-j];
        autoc[j] = sum;
    }
}
static int levinson(const double *r, int order, double *a)
{
    int m, k;
    double E;
    double anew[MAXCH_+2];
    if (r[0] <= 0) return -1;
    for (k = 0; k <= order; k++) a[k] = 0.0;
    a[1] = r[1] / r[0];
    E = r[0] - a[1] * r[1];
    if (E <= 0) return -1;
    for (m = 2; m <= order; m++) {
        double acc = r[m], km;
        for (k = 1; k < m; k++) acc -= a[k] * r[m-k];
        km = acc / E;
        for (k = 0; k <= order; k++) anew[k] = 0.0;
        for (k = 1; k < m; k++) anew[k] = a[k] - km * a[m-k];
        anew[m] = km;
        for (k = 0; k <= order; k++) a[k] = anew[k];
        E -= km * acc;
        if (E <= 0) return -1;
    }
    return 0;
}
static void lpc_coefs(const int32_t *s, int n, int order, int32_t *coef, int *shift)
{
    double *x = (double*)malloc(sizeof(double)*n);
    double r[MAXCH_+1], a[MAXCH_+2];
    int i, sh = 0;
    double mx = 0;
    for (i = 0; i < order; i++) coef[i] = 0;
