    memset(&best, 0, sizeof(best));
    if (!s || !res) { if(s)free(s); if(res)free(res); sf->type = 1; sf->wasted = 0;
                      sf->bits = 8 + (int64_t)n*bits; sf->order = 0; return; }
    for (i = 0; i < n; i++) s[i] = s0[i] >> w;
    { int all = 1; for (i = 1; i < n; i++) if (s[i] != s[0]) { all = 0; break; }
      if (all) { best.type = 0; best.order = 0; best.wasted = w;
                 bestbits = 8 + eff; } }
    if (bestbits < 0 || 8 + (int64_t)n*eff < bestbits) {
        best.type = 1; best.order = 0; best.wasted = w; bestbits = 8 + (int64_t)n*eff;
    }
    for (o = 0; o <= 4 && o < n; o++) {
        int po; int64_t bb = -1, bpo = 0;
        fixed_residual(s, n, o, res);
        for (po = min_part; po <= max_part; po++) {
            int64_t t = residual_cost(res, n - o, o, po);
            if (t < 0) continue;
            if (bb < 0 || t < bb) { bb = t; bpo = po; }
        }
        if (bb >= 0) {
            int64_t b = 8 + (int64_t)o*eff + bb;
            if (bestbits < 0 || b < bestbits) { best.type = 2; best.order = o;
                best.wasted = w; best.po = (int)bpo; bestbits = b; }
        }
    }
    for (o = 1; o <= max_lpc_order && o < n; o++) {
        int prec = 15, shift, po;
        int32_t coef[MAXCH_];
        int64_t bb = -1, bpo = 0;
        lpc_coefs(s, n, o, coef, &shift);
        lpc_residual(s, n, coef, o, shift, res);
        for (po = min_part; po <= max_part; po++) {
            int64_t t = residual_cost(res, n - o, o, po);
            if (t < 0) continue;
