}

static void write_subframe(BitWr *bw, const int32_t *s0, int n, int bits, const SubFrame *sf)
{
    int w = sf->wasted, eff = bits - w, i;
    int32_t *res = (int32_t*)malloc(sizeof(int32_t)*n);
    int o = sf->order;
    if (!res) return;
    bw_bits(bw, 0, 1);
    if (sf->type == 0) bw_bits(bw, 0, 6);
    else if (sf->type == 1) bw_bits(bw, 1, 6);
    else if (sf->type == 2) bw_bits(bw, 0x08 + sf->order, 6);
    else bw_bits(bw, 0x20 + sf->order - 1, 6);
    if (w) { bw_bits(bw, 1, 1); for (i = 0; i < w - 1; i++) bw_bits(bw, 0, 1); bw_bits(bw, 1, 1); }
    else bw_bits(bw, 0, 1);
    if (sf->type == 0) { bw_bits(bw, (uint32_t)(s0[0] >> w) & (eff<32?((1u<<eff)-1):0xffffffffu), eff); free(res); return; }
    if (sf->type == 1) {
        for (i = 0; i < n; i++) bw_bits(bw, (uint32_t)(s0[i] >> w) & (eff<32?((1u<<eff)-1):0xffffffffu), eff);
        free(res); return;
    }
    for (i = 0; i < o; i++) bw_bits(bw, (uint32_t)(s0[i] >> w) & (eff<32?((1u<<eff)-1):0xffffffffu), eff);
    if (sf->type == 3) {
        bw_bits(bw, sf->prec - 1, 4);
        bw_bits(bw, sf->shift, 5);
        for (i = 0; i < o; i++) bw_bits(bw, (uint32_t)sf->coef[i] & ((1u << sf->prec) - 1), sf->prec);
    }
    if (sf->type == 2) fixed_residual(s0, n, o, res);
    else lpc_residual(s0, n, sf->coef, o, sf->shift, res);
    bw_bits(bw, 0, 2);
    bw_bits(bw, sf->po, 4);
    {
        int np = 1 << sf->po, nv = (n - o) >> sf->po, k;
        for (k = 0; k < np; k++) {
            int rp = best_rice_param(res + k*nv, nv);
            int j;
            bw_bits(bw, rp, 4);
            for (j = 0; j < nv; j++) {
                uint32_t u = zigzag(res[k*nv + j]);
                uint32_t q = u >> rp, r = u & ((1u << rp) - 1);
                int t;
                for (t = 0; t < (int)q; t++) bw_bits(bw, 0, 1);
                bw_bits(bw, 1, 1);
                if (rp) bw_bits(bw, r, rp);
            }
        }
    }
    free(res);
}
static int bs_code(int bs, int *el, int *ev)
{
    *el = 0; *ev = 0;
    switch (bs) {
    case 192: return 1; case 576: return 2; case 1152: return 3; case 2304: return 4;
    case 4608: return 5; case 256: return 8; case 512: return 9; case 1024: return 10;
    case 2048: return 11; case 4096: return 12; case 8192: return 13;
    case 16384: return 14; case 32768: return 15;
    }
    if (bs <= 256) { *el = 1; *ev = bs-1; return 6; }
    *el = 2; *ev = bs-1; return 7;
}
static int sr_code(int sr, int *el, int *ev)
{
    *el = 0; *ev = 0;
    switch (sr) {
    case 88200: return 1; case 176400: return 2; case 192000: return 3;
    case 8000: return 4; case 16000: return 5; case 22050: return 6;
    case 24000: return 7; case 32000: return 8; case 44100: return 9;
    case 48000: return 10; case 96000: return 11;
    }
    if (sr % 1000 == 0 && sr/1000 <= 255) { *el = 1; *ev = sr/1000; return 12; }
    if (sr <= 65535) { *el = 2; *ev = sr; return 13; }
    if (sr % 10 == 0 && sr/10 <= 65535) { *el = 2; *ev = sr/10; return 14; }
    *el = 2; *ev = sr & 0xffff; return 13;
}
static int sz_code(int bits)
{
    switch (bits) { case 8: return 1; case 12: return 2; case 16: return 4;
    case 20: return 5; case 24: return 6; case 32: return 7; }
    return 0;
}
static void put_utf8(BitWr *bw, uint32_t v)
{
    if (v < 0x80) { bw_bits(bw, v, 8); return; }
    if (v < 0x800) { bw_bits(bw, 0xC0 | (v >> 6), 8); bw_bits(bw, 0x80 | (v & 0x3f), 8); return; }
    if (v < 0x10000) { bw_bits(bw, 0xE0 | (v >> 12), 8); bw_bits(bw, 0x80 | ((v>>6)&0x3f), 8);
                       bw_bits(bw, 0x80 | (v & 0x3f), 8); return; }
    bw_bits(bw, 0xF0 | (v >> 18), 8); bw_bits(bw, 0x80 | ((v>>12)&0x3f), 8);
    bw_bits(bw, 0x80 | ((v>>6)&0x3f), 8); bw_bits(bw, 0x80 | (v & 0x3f), 8);
}

int flac_encode_chunk(FILE *f, int sr, int ch, int bits, const int32_t *data,
                      int n, int64_t frame_index, int max_lpc_order,
                      int min_part, int max_part)
{
    uint8_t hdr[64];
    int hl = 0, el = 0, ev = 0, sl = 0, sv = 0, bsc, src, szc;
    uint8_t *sub;
    int subcap;
    BitWr bw;
    int c, i;
    int64_t total = 0;
    bsc = bs_code(n, &el, &ev);
    src = sr_code(sr, &sl, &sv);
    szc = sz_code(bits);
    memset(hdr, 0, sizeof(hdr));
    bw_init(&bw, hdr, sizeof(hdr));
    bw_bits(&bw, 0x3ffe, 14); bw_bits(&bw, 0, 1); bw_bits(&bw, 0, 1);
    bw_bits(&bw, bsc, 4); bw_bits(&bw, src, 4);
    bw_bits(&bw, ch-1, 4); bw_bits(&bw, szc, 3); bw_bits(&bw, 0, 1);
    put_utf8(&bw, (uint32_t)frame_index);
    if (el == 1) bw_bits(&bw, ev, 8);
    else if (el == 2) { bw_bits(&bw, (uint32_t)ev >> 8, 8); bw_bits(&bw, ev & 0xff, 8); }
    if (sl == 12) bw_bits(&bw, sv, 8);
    else if (sl == 13 || sl == 14) { bw_bits(&bw, (uint32_t)sv >> 8, 8); bw_bits(&bw, sv & 0xff, 8); }
    hl = bw_bytepos(&bw);
    hdr[hl++] = ff_crc8(hdr, hl);
    subcap = n*ch*bits/8 + 8192 + n*40;
    sub = (uint8_t*)calloc(1, subcap);
    if (!sub) return AVERROR_NOMEM;
    bw_init(&bw, sub, subcap);
    for (c = 0; c < ch; c++) {
        SubFrame sf;
        int32_t tmp[MAXCH_];
        for (i = 0; i < n; i++) tmp[i] = data[(size_t)i*ch + c];
        eval_subframes(tmp, n, bits, max_lpc_order, min_part, max_part, &sf);
        write_subframe(&bw, tmp, n, bits, &sf);
    }
    bw_align(&bw);
    {
        int sublen = bw_bytepos(&bw);
        uint8_t *frame = (uint8_t*)malloc(hl + sublen + 2);
        uint16_t crc;
        if (!frame) { free(sub); return AVERROR_NOMEM; }
        memcpy(frame, hdr, hl);
        memcpy(frame + hl, sub, sublen);
        crc = ff_crc16(frame, hl + sublen);
        frame[hl+sublen] = (uint8_t)(crc >> 8);
        frame[hl+sublen+1] = (uint8_t)(crc & 0xff);
        fwrite(frame, 1, hl+sublen+2, f);
        total = hl + sublen + 2;
        free(frame);
    }
    free(sub);
    return (int)total;
}

void flac_write_header(FILE *f, int sr, int ch, int bits, int64_t total_samples,
                       const char *encoder)
{
    uint8_t si[34];
    uint8_t *vc;
    int vcl, p = 0, l;
    uint64_t v = ((uint64_t)sr << 44) | ((uint64_t)(ch-1) << 41) | ((uint64_t)(bits-1) << 36) |
                 (uint64_t)(total_samples > 0 ? total_samples : 0);
    memset(si, 0, sizeof(si));
    si[0] = 0x12; si[1] = 0x00; si[2] = 0x12; si[3] = 0x00;
    si[10] = (uint8_t)((v >> 40) & 0xff);
    si[11] = (uint8_t)((v >> 32) & 0xff);
    si[12] = (uint8_t)((v >> 24) & 0xff);
    si[13] = (uint8_t)((v >> 16) & 0xff);
    si[14] = (uint8_t)((v >> 8) & 0xff);
    si[15] = (uint8_t)(v & 0xff);
    fwrite("fLaC", 1, 4, f);
    fputc(0x00, f); fputc(0x00, f); fputc(0x00, f); fputc(34, f);
    fwrite(si, 1, 34, f);
    l = (int)strlen(FFM_LAVF);
    vcl = 4 + l + 4 + 4 + (int)strlen(encoder) + 1;
    vc = (uint8_t*)calloc(1, vcl + 16);
    vc[p++] = (uint8_t)(l>>24); vc[p++] = (uint8_t)(l>>16); vc[p++] = (uint8_t)(l>>8); vc[p++] = (uint8_t)l;
    memcpy(vc+p, FFM_LAVF, l); p += l;
    vc[p++]=0; vc[p++]=0; vc[p++]=0; vc[p++]=1;
    l = (int)strlen(encoder) + 1;
    vc[p++] = (uint8_t)(l>>24); vc[p++] = (uint8_t)(l>>16); vc[p++] = (uint8_t)(l>>8); vc[p++] = (uint8_t)l;
    memcpy(vc+p, encoder, l-1); p += l;
    vcl = p;
    fputc(0x00, f); fputc((uint8_t)(vcl>>16), f); fputc((uint8_t)(vcl>>8), f); fputc((uint8_t)vcl, f);
    fwrite(vc, 1, vcl, f);
    free(vc);
    fputc(0x81, f); fputc(0x00); fputc(0x20); fputc(0x00);
    { uint8_t z[256]; int left = 8192; memset(z,0,sizeof(z));
      while (left>0) { int nn = left>256?256:left; fwrite(z,1,nn,f); left-=nn; } }
}

void flac_fix_streaminfo(FILE *f, int64_t min_fs, int64_t max_fs, int64_t total_samples,
                         const uint8_t *md5)
{
    uint8_t b[8];
    int i;
    fseeko(f, 12, SEEK_SET);
    b[0]=(uint8_t)(min_fs>>16); b[1]=(uint8_t)(min_fs>>8); b[2]=(uint8_t)min_fs;
    fwrite(b,1,3,f);
    b[0]=(uint8_t)(max_fs>>16); b[1]=(uint8_t)(max_fs>>8); b[2]=(uint8_t)max_fs;
    fwrite(b,1,3,f);
    if (total_samples >= 0) {
        uint64_t v = (uint64_t)total_samples;
        fseeko(f, 18, SEEK_SET);
        b[0]=(uint8_t)((v>>32)&0x0f); b[1]=(uint8_t)(v>>24); b[2]=(uint8_t)(v>>16);
        b[3]=(uint8_t)(v>>8); b[4]=(uint8_t)v;
        fwrite(b,1,5,f);
    }
    if (md5) {
        fseeko(f, 26, SEEK_SET);
        for (i=0;i<16;i++) fputc(md5[i], f);
    }
    fseeko(f, 0, SEEK_END);
}
