             (int)(sz/1024), tb, audio_bytes? (sz*8.0/dur/1000.0):0.0);
    }
end:
    if (fi) fclose(fi);
    if (fo) fclose(fo);
    free(vc); free(buf); free(fbuf); free(md5ctx);
    return ret;
}

